package com.example

import com.example.ExamQuestionHelper.QSpec

internal object HistoryLiveExamSourcesPrehistoryBank {
  private const val T = "ඓතිහාසික මූලාශ්‍ර හා ප්‍රාග් ඓතිහාසික යුගය"

  private fun q(
    t: String,
    s: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    e: String
  ) = QSpec(t, s, c, listOf(d1, d2, d3), e)

  fun sourcesAndPrehistoryQuestions(): List<QSpec> = listOf(
    q(T, "ලංකා ඉතිහාසය හැදෑරීමේදී ඓතිහාසික මූලාශ්‍ර ප්‍රධාන කොටස් කීයකට බෙදා දැක්වේද?", "දෙකකට (සාහිත්‍ය හා පුරාවිද්‍යාත්මක)", "තුනකට (ලිඛිත, වාචික හා චිත්‍ර)", "හතරකට (දේශීය, විදේශීය, ශිලා හා කාසි)", "පහකට (ගද්‍ය, පද්‍ය, කලා, ගොඩනැගිලි හා කාසි)", "ඓතිහාසික මූලාශ්‍ර සාහිත්‍ය මූලාශ්‍ර හා පුරාවිද්‍යාත්මක මූලාශ්‍ර ලෙස කොටස් දෙකකට බෙදේ."),
    q(T, "ශ්‍රී ලංකාවේ දැනට හමු වී ඇති පැරණිතම දේශීය වංශකතාව කුමක්ද?", "දීපවංශය", "මහාවංශය", "චූලවංශය", "රාජාවලිය", "ක්‍රි.ව. 4 වන සියවසේ පමණ රචිත දීපවංශය ලංකාවේ පැරණිතම වංශකතාවයි."),
    q(T, "මහාවංශයේ පළමු කොටස රචනා කළ හිමිනම කවුද?", "මහානාම හිමි", "බුද්ධඝෝෂ හිමි", "ධර්මකීර්ති හිමි", "මයුරපාද පරිවේණාධිපති හිමි", "අනුරාධපුර මහාවිහාර වාසී මහානාම හිමියන් ක්‍රි.ව. 5-6 සියවස්හි මහාවංශය රචනා කළහ."),
    q(T, "මහාවංශයේ පළමු කොටසින් ආවරණය වන කාලපරිච්ඡේදය කුමක්ද?", "විජය කුමරුගේ සිට මහසෙන් රජ සමය දක්වා", "පණ්ඩුකාභය සිට දුටුගැමුණු රජ සමය දක්වා", "මහසෙන් රජුගේ සිට මහා පරාක්‍රමබාහු දක්වා", "දේවානම්පියතිස්ස සිට වළගම්බා රජු දක්වා", "මහාවංශයේ මුල් කොටස විජයාගමනයේ සිට මහසෙන් රජුගේ අවසානය දක්වා විස්තර කරයි."),
    q(T, "මහාවංශයට පසුව ලියැවුණු අඛණ්ඩ ඉතිහාස ග්‍රන්ථය හැඳින්වෙන්නේ කුමන නමකින්ද?", "චූලවංශය", "ථූපවංශය", "ධාතුවංශය", "නිකාය සංග්‍රහය", "මහසෙන් රජුගෙන් පසු ඉතිහාසය චූලවංශය නමින් හැඳින්වෙන අතිරේක කොටස්වලින් සම්පාදිතය."),
    q(T, "මහාවංශය ලිවීමට පදනම් වූ පැරණි අටුවා ග්‍රන්ථ හැඳින්වූ පොදු නාමය කුමක්ද?", "සීහලට්ඨකතා මහාවංශය", "විසුද්ධිමග්ගය", "පූජාවලිය", "මහාබෝධිවංශය", "මහාවිහාරයේ තිබූ සීහලට්ඨකතා මහාවංශය ඇසුරෙන් පාලි මහාවංශය රචනා විය."),
    q(T, "පහත දැක්වෙන ග්‍රන්ථ අතරින් ශ්‍රී ලංකාවේ ශාසන ඉතිහාසය හැදෑරීමට වඩාත් වැදගත් වන සිංහල ග්‍රන්ථය කුමක්ද?", "නිකාය සංග්‍රහය", "සැළලිහිණි සන්දේශය", "කව්සිළුමිණ", "සිදත් සඟරාව", "දෙවන ජයබාහු රජ දවස රචිත නිකාය සංග්‍රහය ශාසන ඉතිහාසය හා නිකාය භේද පිළිබඳ විස්තර සපයයි."),
    q(T, "දඹදෙණි යුගයේ මයුරපාද පරිවේණාධිපති බුද්ධපුත්‍ර හිමියන් විසින් රචිත ඓතිහාසික තොරතුරු ඇතුළත් ග්‍රන්ථය කුමක්ද?", "පූජාවලිය", "සද්ධර්මරත්නාවලිය", "අමාවතුර", "බුත්සරණ", "පූජාවලියේ 34 වන පරිච්ඡේදය ලංකාවේ රාජවංශය පිළිබඳ වැදගත් තොරතුරු රැසක් සපයයි."),
    q(T, "සීතාවක රාජධානියේ පටන් කෝට්ටේ හා මහනුවර මුල් අවධිය දක්වා දේශපාලන තොරතුරු ලබා ගත හැකි ප්‍රධාන සිංහල වංශකතාව කුමක්ද?", "රාජාවලිය", "දීපවංශය", "මහාබෝධිවංශය", "හත්ථවනගල්ල විහාර වංශය", "සිංහල භාෂාවෙන් රචිත රාජාවලිය විජයගේ සිට දෙවන විමලධර්මසූරිය දක්වා රාජ පරම්පරාව දක්වයි."),
    q(T, "මහාවංශයට ප්‍රථම ලියැවුණු වංශකතා විස්තර වඩාත් පැහැදිලි කරන අටුවා ග්‍රන්ථය කුමක්ද?", "වංසත්ථප්පකාසිනිය", "සමන්තපාසාදිකාව", "අත්තනගලු වංශය", "සද්ධර්මරත්නාකරය", "වංසත්ථප්පකාසිනිය යනු මහාවංශයට ලියැවුණු ටීකා ග්‍රන්ථයයි."),
    q(T, "විනය පිටකයට අටුවාවක් ලෙස බුද්ධඝෝෂ හිමියන් විසින් රචිත කෘතිය කුමක්ද?", "සමන්තපාසාදිකාව", "පපඤ්චසූදනිය", "සුමංගලවිලාසිනිය", "මනෝරථපූරණිය", "සමන්තපාසාදිකාව අනුරාධපුර යුගයේ ශාසනික හා සමාජ තොරතුරු රැසක් අඩංගු ග්‍රන්ථයකි."),
    q(T, "රුවන්වැලි මහා සෑයේ ඉදිකිරීම් හා ධාතු නිධානය පිළිබඳව විස්තර වන වංශකතාව කුමක්ද?", "ථූපවංශය", "දාඨාවංශය", "කේසධාතුවංශය", "සද්ධර්මරත්නාවලිය", "පරාක්‍රම පණ්ඩිත විසින් රචිත සිංහල ථූපවංශය රුවන්වැලිසෑය හා ස්තූප ඉතිහාසය විස්තර කරයි."),
    q(T, "ශ්‍රී දළදා වහන්සේ ලංකාවට වැඩමවීම සහ ඒ හා බැඳුණු ඉතිහාසය විස්තර කෙරෙන ප්‍රධාන වංශකතාව කුමක්ද?", "දාඨාවංශය", "දීපවංශය", "නලාටධාතුවංශය", "මහාබෝධිවංශය", "පොළොන්නරු යුගයේ ධර්මකීර්ති හිමියන් රචනා කළ දාඨාවංශය දළදා ඉතිහාසය විස්තර කරයි."),
    q(T, "කෝට්ටේ යුගයේ රචිත සන්දේශ කාව්‍ය ඉතිහාසය හැදෑරීමේදී වැදගත් වන්නේ ඇයි?", "සමකාලීන නගර, ජන ජීවිතය හා දේශපාලන තොරතුරු ඇතුළත් බැවින්", "ප්‍රාග් ඓතිහාසික ගල් ආයුධ ගැන විස්තර කරන බැවින්", "පෘතුගීසි ආණ්ඩුක්‍රම ව්‍යවස්ථා පිටපත් කර ඇති බැවින්", "අනුරාධපුර වැව් ඉදිකිරීමේ තාක්ෂණය විස්තර කරන බැවින්", "සැළලිහිණි, ගිරා, හංස ආදී සන්දේශ කාව්‍ය කෝට්ටේ සමාජ, ආගමික හා දේශපාලන තොරතුරු දක්වයි."),
    q(T, "සීතාවක හා මහනුවර යුගවල පෘතුගීසි හා ලන්දේසීන්ට එරෙහි යුද්ධ පිළිබඳ තොරතුරු සපයන කාව්‍ය සම්ප්‍රදාය කුමක්ද?", "හටන් කාව්‍ය", "සන්දේශ කාව්‍ය", "ප්‍රශස්ති කාව්‍ය", "ශෘංගාර කාව්‍ය", "සීතාවක හටන, මන්දාරම් පුවත, කොන්ස්තන්තීනු හටන වැනි හටන් කාව්‍ය සමකාලීන යුද තොරතුරු හෙළි කරයි."),
    q(T, "සීතාවක රාජසිංහ රජු හා පෘතුගීසීන් අතර සටන් විස්තර කරන හටන් කාව්‍යය කුමක්ද?", "සීතාවක හටන", "වඩුග හටන", "ඉංග්‍රීසි හටන", "පරංගි හටන", "සීතාවක රාජධානියේ හමුදා ජයග්‍රහණ සීතාවක හටනෙහි කාව්‍යාත්මකව වර්ණනා වේ."),
    q(T, "විදේශීය මූලාශ්‍ර අතර ඉන්දියාවේ මෞර්ය රාජ සභාවේ සිට ලංකාව ගැන ලියූ ග්‍රීක තානාපතිවරයා කවුද?", "මෙගස්තිනීස්", "ටොලමි", "ප්ලිනි", "කොස්මස් ඉන්ඩිකොප්ලූස්ටස්", "මෙගස්තිනීස් සිය 'ඉන්ඩිකා' ග්‍රන්ථයේ ලංකාව 'ටැප්‍රොබේන්' නමින් හඳුන්වා ඇත්දළ හා රන් ගැන ලියා ඇත."),
    q(T, "ලංකාවේ පැරණි සිතියමක් ඇඳ නගර, ගංගා හා වරායන් පිළිබඳ විස්තර කළ ග්‍රීක භූගෝල විද්‍යාඥයා කවුද?", "ක්ලෝඩියස් ටොලමි", "මෙගස්තිනීස්", "ප්ලිනි", "මාකෝ පෝලෝ", "ක්‍රි.ව. 2 වන සියවසේ ටොලමි සිය 'භූගෝල විද්‍යා ප්‍රවේශය' ග්‍රන්ථයේ ටැප්‍රොබේන් සිතියම ඉදිරිපත් කළේය."),
    q(T, "ක්‍රි.ව. 1 වන සියවසේ ලංකාවේ තානාපතිවරුන් රෝමයට ගිය බව සඳහන් කළ රෝම ලේඛකයා කවුද?", "ප්ලිනි", "හෙරොඩෝටස්", "ටොලමි", "ප්‍රොකෝපියස්", "භාතිකාභය රජ සමයේ රෝමයට තානාපති පිරිසක් ගිය බව ජ්‍යෙෂ්ඨ ප්ලිනි සිය කෘතියේ සඳහන් කළේය."),
    q(T, "මහානාම රජ සමයේ ලංකාවට පැමිණ අනුරාධපුරයේ වැඩ සිට චාරිකා සටහන් තැබූ චීන භික්ෂුව කවුද?", "පාහියන් හිමි", "හියුං සාං හිමි", "ඉත් සිං හිමි", "මා හුආන්", "පාහියන් හිමි ක්‍රි.ව. 5 වන සියවසේ ලංකාවට පැමිණ අභයගිරිය, මහාවිහාරය හා දළදා පෙරහැර ගැන ලීවේය."),
    q(T, "ලංකාවට නොපැමිණියද ඉන්දියාවේ සිට ලංකාව ගැන තොරතුරු රැස් කර වාර්තා තැබූ චීන භික්ෂුව කවුද?", "හියුං සාං හිමි", "පාහියන් හිමි", "ෂෙං හෝ", "වං තා යුආන්", "ක්‍රි.ව. 7 වන සියවසේ හියුං සාං හිමි දකුණු ඉන්දියාවේ සිටි ශ්‍රී ලාංකික භික්ෂූන්ගෙන් ලංකාව ගැන තොරතුරු ලීවේය."),
    q(T, "ක්‍රි.ව. 6 වන සියවසේ ලංකාව අන්තර්ජාතික වෙළෙඳ මධ්‍යස්ථානයක් බව සඳහන් කළ 'ක්‍රිස්තියානි භූගෝල විද්‍යාව' කෘතියේ කතුවරයා කවුද?", "කොස්මස් ඉන්ඩිකොප්ලූස්ටස්", "මාකෝ පෝලෝ", "ටොලමි", "ඉබන් බතූතා", "කොස්මස් ඉන්ඩිකොප්ලූස්ටස් ලංකාව 'සෙලෙඩිබා' ලෙස හඳුන්වමින් සේද, කරාබුනැටි හා මැණික් වෙළෙඳාම විස්තර කළේය."),
    q(T, "ගම්පොළ යුගයේ ශ්‍රී ලංකාවට පැමිණි මොරොක්කෝ ජාතික දේශාටකයා කවුද?", "ඉබන් බතූතා", "මාකෝ පෝලෝ", "අබ්දුල් රසාක්", "රොබට් නොක්ස්", "ක්‍රි.ව. 1344 දී ඉබන් බතූතා ලංකාවට පැමිණ ශ්‍රී පාද වන්දනාව, යාපනය හා ගම්පොළ ගැන සටහන් තැබීය."),
    q(T, "17 වන සියවසේ මහනුවර රාජධානියේ සිරකරුවෙකු ලෙස වසර 19ක් සිට 'එදා හෙළදිව' ග්‍රන්ථය රචනා කළ ඉංග්‍රීසි ජාතිකයා කවුද?", "රොබට් නොක්ස්", "ජෝන් ඩොයිලි", "ෆර්නාවෝ ද ක්වේරෝස්", "පිලිප් බැල්ඩියස්", "රොබට් නොක්ස් 1681 දී ලියූ කෘතිය දෙවන රාජසිංහ සමයේ උඩරට සමාජය පිළිබඳ විශිෂ්ට මූලාශ්‍රයකි."),
    q(T, "පෘතුගීසි යුගය පිළිබඳ ලියැවුණු 'ලංකාවේ ආධ්‍යාත්මික හා භෞතික ජයග්‍රහණය' ග්‍රන්ථයේ කතුවරයා කවුද?", "ෆර්නාවෝ ද ක්වේරෝස් පියතුමා", "ජොආඕ රිබෙයිරෝ", "රොබට් නොක්ස්", "රැල්ෆ් පීරිස්", "ක්වේරෝස් පියතුමා පෘතුගීසි ලේඛනාගාර තොරතුරු ඇසුරෙන් කෝට්ටේ හා සීතාවක ඉතිහාසය විස්තර කළේය."),
    q(T, "ලන්දේසි පාලන සමයේ ජනයාගේ ආගමික හා සමාජ තොරතුරු ලියූ ලන්දේසි දේවගැතිවරයා කවුද?", "පිලිප් බැල්ඩියස්", "වැලන්ටයින්", "ජෝන් පයිබස්", "හියු නෙවිල්", "පිලිප් බැල්ඩියස් යාපනය ඇතුළු වෙරළබඩ ප්‍රදේශවල ලන්දේසි පාලන තොරතුරු වාර්තා කළේය."),
    q(T, "සාහිත්‍ය මූලාශ්‍රවල ඇති තොරතුරුවල සත්‍යතාව තහවුරු කර ගැනීමට වඩාත් උපකාරී වන මූලාශ්‍ර වර්ගය කුමක්ද?", "පුරාවිද්‍යාත්මක මූලාශ්‍ර", "ජනකතා මූලාශ්‍ර", "ප්‍රශස්ති කාව්‍ය", "පුරාවෘත්ත", "ශිලා ලේඛන, කාසි හා නටබුන් වැනි පුරාවිද්‍යාත්මක මූලාශ්‍ර සමකාලීන වන අතර පසුව වෙනස් කළ නොහැකිය."),
    q(T, "ශ්‍රී ලංකාවෙන් හමු වී ඇති පැරණිතම ශිලා ලේඛන ලියා ඇති අක්ෂර මාලාව කුමක්ද?", "බ්‍රාහ්මී අක්ෂර", "ග්‍රන්ථ අක්ෂර", "පල්ලව අක්ෂර", "නාගරී අක්ෂර", "මහින්දාගමනයෙන් පසු හෝ ඊට ආසන්න කාලයේ සිට පූර්ව බ්‍රාහ්මී අක්ෂරවලින් ලෙන් ලිපි ලියැවී ඇත."),
    q(T, "ශ්‍රී ලංකාවේ පැරණිතම ශිලා ලේඛන වැඩි වශයෙන් කොටා ඇත්තේ කුමන ස්ථානවලද?", "ගල් ලෙන් කටාරම්වල", "ලෝහ තහඩුවල", "මැටි පුවරුවල", "ගඩොල් කුට්ටිවල", "භික්ෂූන් වහන්සේලාට ගල් ලෙන් පූජා කිරීම දැක්වීම සඳහා ගල් ලෙන් කටාරම්වල පූර්ව බ්‍රාහ්මී ලිපි කොටා ඇත."),
    q(T, "ශිලා ලේඛන හැදෑරීමේ විද්‍යාව හැඳින්වෙන්නේ කුමන නමකින්ද?", "අභිලේඛන විද්‍යාව (Epigraphy)", "නාණක විද්‍යාව (Numismatics)", "පුරාලිපි විද්‍යාව (Paleography)", "මානව විද්‍යාව (Anthropology)", "ගල්, තඹ හෝ වෙනත් දෘඪ මාධ්‍ය මත කොටන ලද ලිපි අධ්‍යයනය කිරීම අභිලේඛන විද්‍යාවයි."),
    q(T, "ශ්‍රී ලංකාවේ සමාජයේ වෛද්‍ය සේවා සහ ආරෝග්‍යශාලා පරිපාලනය ගැන වැදගත් තොරතුරු සපයන පුවරු ලිපිය කුමක්ද?", "මිහින්තලේ පුවරු ලිපිය", "ගල්පොත ලිපිය", "තෝණිගල ලිපිය", "වේවැල්කැටිය ලිපිය", "හතරවන මිහිඳු රජුගේ මිහින්තලේ පුවරු ලිපිය විහාර පාලනය හා වේතන ක්‍රම දැක්වේ."),
    q(T, "වෙළෙඳ නගරයක නීති රීති, මිනුම් දඬු සහ බදු පිළිබඳව කරුණු හෙළි කරන බදුල්ල ටැම් ලිපිය කුමන රජුගේ සමයට අයත්ද?", "හතරවන උදය රජු", "පළමුවන විජයබාහු රජු", "නිශ්ශංකමල්ල රජු", "මහසෙන් රජු", "හෝපිටිගමු වෙළෙඳපොළ පාලනය ගැන සඳහන් බදුල්ල ටැම් ලිපිය හතරවන උදය රජුට අයත් වේ."),
    q(T, "බැංකු කටයුතු හා ධාන්‍ය තැන්පතු ක්‍රම පිළිබඳව පැරණි ලංකාවෙන් හමුවන ප්‍රධානතම ශිලා ලේඛනය කුමක්ද?", "තෝණිගල සෙල්ලිපිය", "පනාකඩුව තඹ සන්නස", "වල්ලිපුරම් රන් සන්නස", "ගඩලාදෙණිය ලිපිය", "සිරිමෙවන් රජ සමයට අයත් තෝණිගල ගිරි ලිපිය වී, උඳු හා මුං තැන්පත් කර පොලියෙන් දන් දීම විස්තර කරයි."),
    q(T, "ශ්‍රී ලංකාවෙන් හමු වී ඇති පැරණිතම තඹ සන්නස ලෙස සැලකෙන්නේ කුමක්ද?", "පනාකඩුව තඹ සන්නස", "ඔරුවල තඹ සන්නස", "දෙවුන්දර තඹ සන්නස", "දඩිගම තඹ සන්නස", "පළමුවන විජයබාහු රජු බුදල්නාවන්ට දුන් වරප්‍රසාද දැක්වෙන පනාකඩුව තඹ සන්නස පැරණිතම තඹ සන්නසයි."),
    q(T, "වසභ රජුගේ පාලන සමය සහ නාගදීප පාලනය ගැන තොරතුරු හෙළි කරන වටිනා මූලාශ්‍රය කුමක්ද?", "වල්ලිපුරම් රන් සන්නස", "පනාකඩුව තඹ සන්නස", "බදුල්ල ටැම් ලිපිය", "අම්බලන්තොට ලිපිය", "යාපනය වල්ලිපුරමින් හමු වූ රන් සන්නස වසභ රජුගේ ඉසිගිරිය ඇමති නාගදීපය පාලනය කළ බව දක්වයි."),
    q(T, "ශ්‍රී ලංකාවේ විශාලතම සෙල්ලිපිය ලෙස සැලකෙන ගල්පොත ලිපිය කරවන ලද්දේ කුමන රජු විසින්ද?", "නිශ්ශංකමල්ල රජු", "මහා පරාක්‍රමබාහු රජු", "පළමුවන විජයබාහු රජු", "සේන රජු", "පොළොන්නරුවේ ගල්පොත ලිපිය නිශ්ශංකමල්ල රජුගේ පරපුර හා සේවාවන් විස්තර කරයි."),
    q(T, "ගමක නීතිය හා සාමය ආරක්ෂා කිරීම සඳහා දසගම් ඇත්තන්ට පැවරූ වගකීම් දක්වන සෙල්ලිපිය කුමක්ද?", "වේවැල්කැටිය සෙල්ලිපිය", "තෝණිගල සෙල්ලිපිය", "රුවන්වැලිසෑය ලිපිය", "මිහින්තලේ ලිපිය", "හතරවන මිහිඳු රජුගේ වේවැල්කැටිය ටැම් ලිපිය ග්‍රාමීය අධිකරණ හා දඬුවම් ක්‍රම පෙන්වා දෙයි."),
    q(T, "අනුරාධපුර රජරට ශිෂ්ටාචාරයේ මුල් කාලයේ කහපණ කාසි සමඟම භාවිත වූ දේශීය කාසි වර්ගය කුමක්ද?", "හස් එබූ කාසි (පුරාණ කාසි)", "මස්ස කාසි", "පගෝඩා කාසි", "ඩොයිට් කාසි", "දේශීය වශයෙන් අච්චු ගසා භාවිත කළ හස් එබූ කාසි හෙවත් කහපණ පැරණිතම කාසි වර්ගයකි."),
    q(T, "පොළොන්නරු යුගයේ සිට භාවිතයට පැමිණි රජුගේ නම සහ රූපය සහිත පැරණි කාසි වර්ගය කුමක්ද?", "මස්ස කාසි (තඹ මස්ස)", "රන් කහවණු", "අක කාසි", "ස්වස්තික කාසි", "පළමුවන විජයබාහු, පරාක්‍රමබාහු හා නිශ්ශංකමල්ල රජවරුන්ගේ නම් සහිත මස්ස කාසි බහුලව හමු වී ඇත."),
    q(T, "පැරණි කාසි පිළිබඳව අධ්‍යයනය කරන විෂය ක්ෂේත්‍රය හැඳින්වෙන්නේ කුමන නමකින්ද?", "නාණක විද්‍යාව", "අභිලේඛන විද්‍යාව", "වංශකතා විද්‍යාව", "භූගර්භ විද්‍යාව", "කාසි අධ්‍යයනය තුළින් ආර්ථික තත්ත්වය, වෙළෙඳ සබඳතා සහ පාලන සමයන් හඳුනා ගත හැකිය."),
    q(T, "අනුරාධපුර යුගයේ භාවිත වූ බවට තහවුරු වී ඇති විශේෂ ලක්ෂණ සහිත තඹ කාසියක් වන්නේ කුමක්ද?", "ලක්ෂ්මී කාසිය", "වොකාට් කාසිය", "පවුම් කාසිය", "රුපියල් කාසිය", "ලක්ෂ්මී දේවියගේ රූපය සහිත කාසි සහ ස්වස්තික කාසි අනුරාධපුර යුගයේ හමුවේ."),
    q(T, "ශ්‍රී ලංකාවේ බටහිර හා දකුණු වෙරළ තීරයෙන් රෝම කාසි විශාල ප්‍රමාණයක් හමුවීමෙන් තහවුරු වන්නේ කුමක්ද?", "රෝම අධිරාජ්‍යය සමඟ පැවති සමෘද්ධිමත් විදේශ වෙළෙඳාම", "රෝම හමුදා ලංකාව ආක්‍රමණය කළ බව", "රෝම ජාතිකයන් ලංකාව පාලනය කළ බව", "රෝම අධිරාජ්‍යය ලංකාවට යටත් විජිතයක් වූ බව", "ක්‍රි.ව. 4-5 සියවස්වල රෝම තඹ කාසි බහුලව හමුවීම විදේශ වෙළෙඳ සබඳතා සනාථ කරයි."),
    q(T, "පුරාවිද්‍යාත්මක කැණීම්වලින් හමුවන ඉපැරණි කාල නිර්ණ ක්‍රම අතර කාබනික ද්‍රව්‍යවල වයස මැනීමට යොදාගන්නා ප්‍රධාන ක්‍රමය කුමක්ද?", "කාබන් 14 (C-14) කාලනිර්ණ ක්‍රමය", "පොටෑසියම්-ආගන් ක්‍රමය", "යුරේනියම් ක්‍රමය", "තාපසංදීප්ත ක්‍රමය", "අඟුරු, අස්ථි හා බෙලිකටු වැනි කාබනික අවශේෂවල කාලය මැනීමට C-14 ක්‍රමය භාවිත කෙරේ."),
    q(T, "මනුෂ්‍යයා ලිවීම ආරම්භ කිරීමට පෙර කාලපරිච්ඡේදය හැඳින්වෙන්නේ කුමන නමකින්ද?", "ප්‍රාග් ඓතිහාසික යුගය", "පූර්ව ඓතිහාසික යුගය", "ඓතිහාසික යුගය", "මධ්‍යතන යුගය", "ලිඛිත මූලාශ්‍ර හමු නොවන, ගල් ආයුධ භාවිත කළ මුල් යුගය ප්‍රාග් ඓතිහාසික යුගයයි."),
    q(T, "ලිඛිත සාක්ෂි නැති නමුත් පුරාවිද්‍යාත්මක සාධක ඇති ප්‍රාග් ඓතිහාසික යුගයත් ඓතිහාසික යුගයත් අතර අන්තර්කාලීන යුගය කුමක්ද?", "පූර්ව ඓතිහාසික (මූල ඓතිහාසික) යුගය", "පුරාශිලා යුගය", "නවශිලා යුගය", "යටත්විජිත යුගය", "යකඩ තාක්ෂණය, වී ගොවිතැන හා මෙගලිතික සුසාන භූමි ඇති කාලය මූල ඓතිහාසික යුගය ලෙස හැඳින්වේ."),
    q(T, "ශ්‍රී ලංකාවේ ප්‍රාග් ඓතිහාසික මානවයා විද්‍යාත්මකව හඳුන්වනු ලබන නාමය කුමක්ද?", "බලංගොඩ මානවයා (Homo sapiens balangodensis)", "ජාවා මානවයා (Homo erectus)", "නියැන්ඩර්තාල් මානවයා", "පීකිං මානවයා", "බෙල්ලන්බැඳි පැලැස්සෙන් හමු වූ ඇටසැකිලි අනුව ආචාර්ය පී.ඊ.පී. දැරණියගල මහතා බලංගොඩ මානවයා නම් කළේය."),
    q(T, "බලංගොඩ මානවයා හා බැඳුණු දකුණු ආසියාවේ පැරණිතම නූතන මානව ෆොසිල අවශේෂ හමු වූ කළුතර දිස්ත්‍රික්කයේ ලෙන කුමක්ද?", "පාහියන්ගල ලෙන", "බටදොඹලෙන", "කිතුල්ගල බෙලිලෙන", "සීගිරිය පොතාන ලෙන", "බුලත්සිංහල පාහියන්ගල ලෙනෙන් වසර 38,000කට වඩා පැරණි මානව අවශේෂ හමු වී ඇත."),
    q(T, "බලංගොඩ මානවයා ජ්‍යාමිතික හැඩැති ක්ෂුද්‍ර ශිලා මෙවලම් භාවිත කළ බවට සාධක හමු වූ කුරුවිට පිහිටි ලෙන කුමක්ද?", "බටදොඹලෙන", "රාවණා ඇල්ල ලෙන", "අළුලෙන", "ෆාහියන් ලෙන", "රත්නපුර කුරුවිට බටදොඹලෙන ප්‍රාග් ඓතිහාසික ජනාවාසයක් ලෙස කැණීම්වලදී තහවුරු වී ඇත."),
    q(T, "ශ්‍රී ලංකාවේ මධ්‍යශිලා යුගයේ මානවයා භාවිත කළ ඉතා කුඩා ගල් ආයුධ හැඳින්වෙන්නේ කුමන නමකින්ද?", "ක්ෂුද්‍ර ශිලා මෙවලම් (Microliths)", "අත් පොරෝ", "ලෝකඩ කඩු", "වීදුරු පිහි", "තිරුවාණ හා කහඳ ගල්වලින් සැකසූ සෙන්ටිමීටර කිහිපයක් දිග ජ්‍යාමිතික ගල් ආයුධ ක්ෂුද්‍ර ශිලා මෙවලම් නම් වේ."),
    q(T, "ප්‍රාග් ඓතිහාසික මානවයාගේ ප්‍රධාන ආහාර වේල කුමක් වීද?", "දඩයම් කළ සතුන්ගේ මස් හා වනයෙන් රැස් කළ පලතුරු හා අල වර්ග", "වී ගොවිතැනින් ලබා ගත් බත්", "තේ සහ කෝපි පාන", "වෙළෙඳපොළෙන් මිලදී ගත් ධාන්‍ය", "මධ්‍යශිලා යුගයේ මිනිසා දඩයමෙන් සහ රැස් කිරීමෙන් යැපුණි."),
    q(T, "බෙල්ලන්බැඳි පැලැස්ස ප්‍රාග් ඓතිහාසික එළිමහන් කඳවුරු භූමිය පිහිටා ඇත්තේ කුමන දිස්ත්‍රික්කයේද?", "රත්නපුර දිස්ත්‍රික්කයේ (ඇඹිලිපිටිය ආසන්නයේ)", "අනුරාධපුර දිස්ත්‍රික්කයේ", "යාපනය දිස්ත්‍රික්කයේ", "මඩකලපුව දිස්ත්‍රික්කයේ", "වලවේ ගඟ ආශ්‍රිත බෙල්ලන්බැඳි පැලැස්ස එළිමහන් ජනාවාසයක සාධක හමු වූ ස්ථානයකි."),
    q(T, "බලංගොඩ මානවයා කැකුණ ඇට වැනි වියළි ඇට වර්ග ආහාරයට ගත් බවට සාධක හමුවන්නේ කුමන ආකාරයෙන්ද?", "පිළිස්සුණු කැකුණ ඇට කටු හා ඇඹරුම් ගල් හමුවීමෙන්", "සෙල්ලිපිවල සඳහන් වීමෙන්", "වංශකතාවල ලියැවී තිබීමෙන්", "විදේශීය සටහන්වලින්", "කිතුල්ගල බෙලිලෙන වැනි ස්ථානවලින් පිළිස්සුණු කැකුණ ඇට හා තැලුම් ගල් හමු වී තිබේ."),
    q(T, "ප්‍රාග් ඓතිහාසික මිනිසුන් තම මළගිය ඥාතීන් කෙරෙහි ගෞරවයක් හෝ අභිචාර විධි පැවැත්වූ බවට හමුවන ප්‍රබල සාධකය කුමක්ද?", "සිරුරුවල ගුරුගල් (රතු හිරිගල්) ආලේප කර ජීවත් වූ ලෙන් තුළම වැළලීම", "පිරමීඩ ගොඩනැගීම", "රන් ආලේපිත පෙට්ටිවල තැන්පත් කිරීම", "මුහුදේ පා කර හැරීම", "රාවණා ඇල්ල හා බටදොඹලෙන ආදී තැන්වල මිනී ඇටකටු මත ගුරුගල් ආලේප කළ බවට සාධක ඇත."),
    q(T, "මධ්‍යශිලා යුගයේ මානවයා මුහුදුබඩ පරිසරය සමඟ සම්බන්ධතා පැවැත්වූ බවට කඳුකර ලෙන්වලින් හමු වූ සාධකය කුමක්ද?", "ලුණු හා මුහුදු බෙලි කටු", "මුහුදු නැව් කොටස්", "කොරල්පර ගොඩනැගිලි", "විදේශීය කාසි", "මධ්‍යම කඳුකරයේ හා තෙත් කලාපීය ලෙන්වලින් මුහුදු බෙලි කටු හමුවීමෙන් වෙරළබඩ ගමන් සනාථ වේ."),
    q(T, "පාහියන්ගල හා බෙලිලෙන ආශ්‍රිත කැණීම්වලින් බලංගොඩ මානවයා සමඟ හමු වූ දැනට ලංකාවෙන් වඳ වී ගිය සත්ත්ව විශේෂය කුමක්ද?", "ගෞර ගවයා (Gaur) සහ හිපපොටේමස්/රයිනෝසිරස් විශේෂ", "ඩයිනෝසරයා", "මැමත් ඇතා", "කැන්ගරුවා", "රත්නපුර මැණික් පතල් හා ප්‍රාග් ඓතිහාසික ස්තරවලින් හිපපොටේමස්, රයිනෝසිරස් හා ගෞර ගව අවශේෂ හමු වී ඇත."),
    q(T, "ශ්‍රී ලංකාවේ පැරණිතම ජ්‍යාමිතික ක්ෂුද්‍ර ශිලා මෙවලම් නිපදවා ඇති ප්‍රධාන ඛනිජ වර්ග මොනවාද?", "තිරුවාණ (Quartz) සහ කහඳ (Chert)", "කළුගල් සහ හුණුගල්", "මිනිරන් සහ අබ්‍රක", "රත්‍රන් සහ තඹ", "සුදු තිරුවාණ හා කහඳ ගල් තියුණු දාර සහිත කුඩා ආයුධ තැනීමට ඉතා සුදුසු විය."),
    q(T, "ශ්‍රී ලංකාවේ වියළි කලාපයේ පැරණිතම ප්‍රාග් ඓතිහාසික සාධක හමු වී ඇති බූන්දල-පතිරාජවෙල ප්‍රදේශයේ ස්ථර හඳුන්වන්නේ කුමන නමින්ද?", "ඉරණමඩු පස් ස්තරය (Iramadu Formation)", "රතු පස් තට්ටුව", "කළු ගල් තට්ටුව", "මැටි තට්ටුව", "බූන්දල හා පතිරාජවෙල රතු වැලි කඳු හෙවත් ඉරණමඩු පස් ස්තරයෙන් වසර ලක්ෂයකට පෙර ගල් ආයුධ හමු වී ඇත."),
    q(T, "පූර්ව ඓතිහාසික (මූල ඓතිහාසික) යුගයේ ප්‍රධාන අනන්‍යතා ලක්ෂණයක් වන්නේ කුමක්ද?", "මෙගලිතික සුසාන භූමි, යකඩ භාවිතය හා කළු-රතු මැටි බඳුන්", "පමණක් ගල් ආයුධ භාවිතය", "පෘතුගීසි බලකොටු ඉදිකිරීම", "පාලි වංශකතා රචනය", "මූල ඓතිහාසික යුගයේදී යකඩ තාක්ෂණය, ස්ථිර ජනාවාස හා විධිමත් සුසාන චාරිත්‍ර ඇති විය."),
    q(T, "ශ්‍රී ලංකාවේ ප්‍රකට මෙගලිතික සුසාන භූමියක් වන 'ඉබ්බන්කටුව' පිහිටා ඇත්තේ කුමන ප්‍රදේශයේද?", "දඹුල්ල ආසන්නයේ (මාතලේ දිස්ත්‍රික්කයේ)", "හම්බන්තොට", "මන්නාරම", "මඩකලපුව", "දඹුල්ල ඉබ්බන්කටුව ක්‍රි.පූ. 6 වන සියවස තරම් පැරණි ගල් පුවරු සුසාන සංකීර්ණයකි."),
    q(T, "විශාල මැටි බරණි තුළ මළවුන්ගේ අවශේෂ තැන්පත් කළ 'බරණි සුසාන' (Urn Burials) හමු වී ඇති ප්‍රධාන ස්ථානය කුමක්ද?", "පොම්පරිප්පුව", "සීගිරිය", "කැලණිය", "මහියංගණය", "පුත්තලම ආසන්න පොම්පරිප්පුව මූල ඓතිහාසික යුගයේ බරණි සුසාන භූමියක් ලෙස ප්‍රකටය."),
    q(T, "කළු-රතු මැටි බඳුන් (Black and Red Ware) හා ලෝහ තාක්ෂණය මෙරට මූල ඓතිහාසික ජනාවාසවල දක්නට ලැබෙන්නේ කුමන කාලයේ සිටද?", "ක්‍රි.පූ. 900 - 600 පමණ සිට", "ක්‍රි.ව. 500 පමණ සිට", "ක්‍රි.ව. 1505 සිට", "ක්‍රි.ව. 1000 සිට", "අනුරාධපුර ඇතුළුනුවර කැණීම් අනුව ක්‍රි.පූ. 900 පමණ සිට යකඩ හා කළු-රතු මැටි බඳුන් භාවිතය තහවුරු වී ඇත."),
    q(T, "සමනලවැව ප්‍රදේශයෙන් හමු වූ පුරාවිද්‍යාත්මක සාධක මගින් හෙළි වන්නේ පැරණි ලංකාවේ කුමන විශේෂ තාක්ෂණයද?", "සුළං බලයෙන් ක්‍රියාත්මක වූ යකඩ හා වානේ උණු කිරීමේ උදුන්", "රෙදි වියන යන්ත්‍ර", "වීදුරු නිපදවීම", "කඩදාසි නිෂ්පාදනය", "මෝසම් සුළං භාවිත කරමින් උසස් තත්ත්වයේ වානේ නිපදවූ උදුන් සමනලවැවින් හමු වී ඇත."),
    q(T, "මූල ඓතිහාසික යුගයේ සමාජ සංවිධානයේදී හමුවන මැටි බඳුන් මත කොටා තිබූ පැරණි සංකේත හඳුන්වන්නේ කුමන නමින්ද?", "ග්‍රැෆිටි සංකේත (Graffiti Marks)", "බ්‍රාහ්මී ගීත", "නාගරී අක්ෂර", "දෙමළ සෙල්ලිපි", "හිමිකරු හෝ කුලය හඳුනා ගැනීමට මැටි බඳුන් මත සටහන් කළ සංකේත ග්‍රැෆිටි ලෙස හැඳින්වේ."),
    q(T, "මහාවංශයේ කතුවරයා විසින් කෘතිය රචනා කිරීමේදී අනුගමනය කළ ප්‍රධාන ආගමික හා සංස්කෘතික අරමුණ කුමක්ද?", "බුදු සසුනේ උන්නතිය හා 'සුජන පහන් සංවේගය' ඇති කිරීම", "යුද කලාව ඉගැන්වීම", "වෙළෙඳ ගිණුම් පවත්වා ගැනීම", "විදේශිකයන්ට වීසා නිකුත් කිරීම", "මහාවංශයේ සෑම පරිච්ඡේදයකම අවසානයේ 'සුජනප්පසාද සංවේගත්ථාය' යනුවෙන් අරමුණ දක්වා ඇත."),
    q(T, "ප්‍රාග් ඓතිහාසික යුගයේ සිට ඓතිහාසික යුගයට පරිවර්තනය වීම පෙන්නුම් කරන ප්‍රධාන සංස්කෘතික සංධිස්ථානය කුමක්ද?", "කෘෂිකර්මාන්තය, යකඩ භාවිතය සහ ලේඛන කලාව ආරම්භ වීම", "මුහුදු යාත්‍රා විනාශ වීම", "සියලු ලෙන් අත්හැර වනගත වීම", "කාසි භාවිතය නතර වීම", "ආහාර නිෂ්පාදන ආර්ථිකය හා අක්ෂර භාවිතය ඓතිහාසික යුගයක ආරම්භය සලකුණු කරයි."),
    q(T, "රන්චමඩම (රත්නපුර දිස්ත්‍රික්කයේ) කැණීම්වලින් පැරණි ශ්‍රී ලංකාවේ කුමන යුගය පිළිබඳ වැදගත් තොරතුරු හමු වීද?", "මූල ඓතිහාසික යුගයේ ගෘහ නිර්මාණ හා සුසාන චාරිත්‍ර", "ලන්දේසි බලකොටු", "බ්‍රිතාන්‍ය දුම්රිය මාර්ග", "කෝට්ටේ සාහිත්‍යය", "රන්චමඩමින් වරිච්චි බිත්ති සහිත නිවාස හා මැටි බඳුන් සුසාන හමු වී ඇත."),
    q(T, "පුරාවිද්‍යාත්මක සාධක අනුව අනුරාධපුර ඇතුළුනුවර නගරය ක්‍රි.පූ. කුමන කාලයේ සිට ජනාවාස වී පැවති බව තහවුරු වේද?", "ක්‍රි.පූ. 900 පමණ සිට", "ක්‍රි.ව. 300 පමණ සිට", "ක්‍රි.ව. 1000 පමණ සිට", "ක්‍රි.පූ. 100 පමණ සිට", "ආචාර්ය ශිරාන් දැරණියගලගේ කැණීම් අනුව අනුරාධපුර ඇතුළුනුවර ක්‍රි.පූ. 900 සිට ජනාවාසව පැවතුණි."),
    q(T, "ශ්‍රී ලංකාවේ ලිඛිත ඉතිහාසය සඳහා පදනම සැපයූ බ්‍රාහ්මී අක්ෂර සොයා ගත් ප්‍රධාන ස්ථාන අතර අනුරාධපුර ඇතුළුනුවරින් හමු වූ මැටි බඳුන් කැබලි කුමන කාලයට අයත්ද?", "ක්‍රි.පූ. 6-5 සියවස්වලට", "ක්‍රි.ව. 8 වන සියවසට", "ක්‍රි.ව. 14 වන සියවසට", "ක්‍රි.ව. 2 වන සියවසට", "අනුරාධපුර ඇතුළුනුවරින් මහින්දාගමනයට පෙර ක්‍රි.පූ. 6-5 සියවස්වලට අයත් බ්‍රාහ්මී අක්ෂර සහිත මැටි බඳුන් හමු වී ඇත."),
    q(T, "කිතුල්ගල බෙලිලෙන ප්‍රාග් ඓතිහාසික කැණීම්වලදී මානව ජනාවාස කොපමණ කලක් පැවති බව අනාවරණය වීද?", "වසර 30,000කට ආසන්න කාලයක්", "වසර 500ක් පමණක්", "වසර 1,000ක් පමණක්", "වසර 2,000ක් පමණක්", "කිතුල්ගල බෙලිලෙන දීර්ඝ කාලීන ප්‍රාග් ඓතිහාසික මානව වාසස්ථානයක් ලෙස තහවුරු වී ඇත."),
    q(T, "ශ්‍රී ලංකාවේ ප්‍රාග් ඓතිහාසික ජනාවාස අධ්‍යයනය කිරීමේදී 'මධ්‍යශිලා යුගය' ලෙස හඳුන්වන්නේ කුමක්ද?", "ක්ෂුද්‍ර ශිලා ආයුධ භාවිත කළ දඩයම් හා ආහාර රැස් කිරීමේ යුගය", "ලෝකඩ කඩු භාවිත කළ යුගය", "කෘෂිකාර්මික යන්ත්‍ර භාවිත කළ යුගය", "මහා දාගැබ් ඉදිකළ යුගය", "ලංකාවේ මධ්‍යශිලා යුගය වසර 38,000 සිට 3,000 පමණ දක්වා විහිදේ."),
    q(T, "ප්‍රාග් ඓතිහාසික යුගයේ මානවයා ගින්දර භාවිත කළ බවට හමුවන පැහැදිලි පුරාවිද්‍යාත්මක සාධකය කුමක්ද?", "ලෙන් ස්තරවලින් පිළිස්සුණු සත්ත්ව ඇටකටු හා අඟුරු තට්ටු හමුවීම", "විදුලි පන්දම් හමුවීම", "ලිඛිත පොත්පත් හමුවීම", "සෙල්ලිපිවල ගිනි පිළිබඳ වර්ණනා කිරීම", "පාහියන්ගල, බෙලිලෙන වැනි ස්ථානවලින් අළු, අඟුරු හා පිළිස්සුණු අස්ථි හමුවී ඇත."),
    q(T, "ලංකාවේ මූල ඓතිහාසික යුගයේ සුසාන චාරිත්‍ර අධ්‍යයනය කිරීමේදී හමුවන 'ශිලා මංජුසා සුසාන' (Cist Burials) හඳුනාගෙන ඇති තවත් ස්ථානයක් කුමක්ද?", "රාංචමඩම සහ යටිගල්පොත්ත", "කොළඹ කොටුව", "ගාලු කොටුව", "ත්‍රිකුණාමලය කෝවිල", "ඉබ්බන්කටුව මෙන්ම යටිගල්පොත්ත, කලාවැව ආශ්‍රිතවද ශිලා මංජුසා සුසාන හමුවේ."),
    q(T, "පුරාවිද්‍යාත්මක කැණීම්වලින් හමු වී ඇති ශ්‍රී ලංකාවේ පැරණිතම හීලෑ කළ සත්ත්වයාගේ අවශේෂ අයත් වන්නේ කුමන සත්ත්වයාටද?", "බල්ලා (Canis familiaris)", "අශ්වයා", "ඔටුවා", "සිංහයා", "නිල්ගල හා බෙල්ලන්බැඳි පැලැස්සෙන් හීලෑ බල්ලාගේ අස්ථි හමු වී ඇත."),
    q(T, "බටදොඹලෙන හා පාහියන්ගලින් හමු වූ මානව හිස් කබල් අනුව බලංගොඩ මානවයාගේ ශරීර ලක්ෂණ ගැන කිව හැක්කේ කුමක්ද?", "ශක්තිමත් හකු හා විශාල දත් පිහිටි පුළුල් නළලක් සහිත වූ බව", "ඉතා කුඩා මිටි මිනිසුන් වූ බව", "හිස් කබල්වල දත් නොතිබූ බව", "නියැන්ඩර්තාල් වර්ගයට අයත් වූ බව", "බලංගොඩ මානවයා දඩයම් ජීවිතයට හුරු වූ ශක්තිමත් අස්ථි පද්ධතියකින් යුක්ත විය."),
    q(T, "ශ්‍රී ලංකාවේ ඉතිහාසය ගොඩනැගීමේදී චූලවංශයේ පළමු කොටස සම්පාදනය කළ බවට සැලකෙන භික්ෂුව කවුද?", "ධම්මකිත්ති හිමි", "මහානාම හිමි", "බුද්ධඝෝෂ හිමි", "වැලිවිට සරණංකර හිමි", "දෙවන පරාක්‍රමබාහු රජ සමයේ වැඩ සිටි ධම්මකිත්ති හිමි චූලවංශයේ පළමු කොටස ලියූ බව පිළිගැනේ."),
    q(T, "මහාචාර්ය සෙනරත් පරණවිතාන මහතා ප්‍රකාශයට පත් කළ 'Inscriptions of Ceylon' ග්‍රන්ථ මාලාව මගින් ඉටු වූ සේවය කුමක්ද?", "බ්‍රාහ්මී හා පසුකාලීන ශිලා ලේඛන කියවා පරිවර්තනය කර ප්‍රකාශයට පත් කිරීම", "පෘතුගීසි පොත් පරිවර්තනය කිරීම", "විදේශීය කාසි එකතු කිරීම", "මහනුවර චිත්‍ර පිටපත් කිරීම", "මහාචාර්ය පරණවිතාන මහතා ලංකාවේ සිය ගණනක් වූ බ්‍රාහ්මී ශිලා ලේඛන විද්‍යාත්මකව ප්‍රකාශයට පත් කළේය."),
    q(T, "කුරුණෑගල රාජධානි සමයේ ලියැවුණු 'දළදා සිරිත' ග්‍රන්ථය ඓතිහාසික වශයෙන් වැදගත් වන්නේ කුමන කරුණක් සඳහාද?", "දළදා පූජා විධි, රාජ්‍ය චාරිත්‍ර හා සමකාලීන රාජ්‍ය නීති විස්තර කිරීමට", "යාපනය රාජධානියේ නීති දැක්වීමට", "ලන්දේසි වෙළෙඳ ගිවිසුම් දැක්වීමට", "දකුණු ඉන්දීය නාවික සටන් විස්තර කිරීමට", "හතරවන පරාක්‍රමබාහු සමයේ ලියැවුණු දළදා සිරිතෙහි දළදා වහන්සේට කෙරෙන රාජ්‍ය චාරිත්‍ර දැක්වේ."),
    q(T, "මහාවංශයේ සඳහන් වන රජවරුන් පිළිබඳ විස්තර සෙල්ලිපි මගින් තහවුරු වීමට නිදසුනක් වන්නේ කුමක්ද?", "මිහිඳු හිමියන්ගේ ගෝලයන් හා උත්තිය රජු ගැන මිහින්තලේ ලෙන් ලිපිවල සඳහන් වීම", "දෙවන ලෝක යුද්ධය ගැන සෙල්ලිපිවල තිබීම", "පෘතුගීසීන්ගේ නම් බ්‍රාහ්මී ලිපිවල තිබීම", "විජය කුමරුගේ උප්පැන්න සහතිකය හමුවීම", "මිහින්තලේ හා රජගල ශිලා ලේඛන මගින් මහාවංශයේ එන දේවානම්පියතිස්ස, උත්තිය, දුටුගැමුණු ආදී රජවරු සනාථ වේ."),
    q(T, "රජගල (අම්පාර) පුරාවිද්‍යා භූමියෙන් හමු වූ 'යේ ඉමදීප පඨමය ආගතා' යන ලිපියෙන් කුමන ඓතිහාසික පුවත සනාථ වේද?", "මිහිඳු හිමියන් හා ඉට්ඨිය හිමියන් ලංකාවට වැඩම කළ බව", "විජය කුමරු තම්බපණ්ණියට ගොඩබට බව", "චෝල හමුදා පැමිණි බව", "මහා පරාක්‍රමබාහු යුද ජයග්‍රහණය ලැබූ බව", "රජගල ස්තූපය අසල ඇති එම ලිපිය මිහිඳු හිමියන්ගේ භෂ්මාවශේෂ නිධන් කළ ස්ථානය තහවුරු කරයි."),
    q(T, "පුරාවිද්‍යාත්මක මූලාශ්‍ර අතර 'සිරිපතුල් ගල්' හා 'බෝධිඝර' නටබුන් මගින් පෙන්නුම් කෙරෙන පැරණි බෞද්ධ සම්ප්‍රදාය කුමක්ද?", "බුදුරජාණන් වහන්සේගේ ප්‍රතිමා නෙළීමට පෙර සංකේත වන්දනාව පැවති බව", "හින්දු දේවාල පමණක් පැවති බව", "බුදුදහම මහායානික වූ බව", "ගල් නෙළීම තහනම් කර තිබූ බව", "මුල් බෞද්ධ සමාජයේ බුදුන් වහන්සේ වෙනුවට සිරිපතුල්, ආසන හා බෝධිය වන්දනා කළ බව පෙනේ."),
    q(T, "පළමු පරාක්‍රමබාහු රජු විසින් රජරට භික්ෂූන් වහන්සේලා සමඟි කර සම්පාදනය කළ විනය නීති සංග්‍රහය කුමන ශිලා ලේඛනයේ කොටා ඇත්ද?", "ගල් විහාර කතිකාවත (පොළොන්නරු කතිකාවත)", "බදුල්ල ටැම් ලිපිය", "තෝණිගල සෙල්ලිපිය", "සීගිරි කුරුටු ගී", "පොළොන්නරුවේ ගල් විහාරයේ පර්වත බිත්තියක පරාක්‍රමබාහු කතිකාවත කොටා තිබේ."),
    q(T, "දඹදෙණි රාජධානියේ වියත් ජනතාව විසින් සීගිරියේ කැටපත් පවුරේ ලියන ලද කුරුටු ගීවල ප්‍රධාන වටිනාකම කුමක්ද?", "අනුරාධපුර යුගයේ සිංහල භාෂාවේ හා සාහිත්‍ය රසඥතාවේ දියුණුව පෙන්වීම", "කෘෂිකාර්මික බදු අනුපාත දැක්වීම", "විදේශීය යුද සැලසුම් ලිවීම", "පෘතුගීසි වචන පුරුදු වීම", "ක්‍රි.ව. 8-10 සියවස්වල සිංහල කවි හා අක්ෂර රූප කුරුටු ගී මගින් සුරැකිව පවතී."),
    q(T, "අනුරාධපුර යුගයේ විශාලතම ස්තූපවල ඉදිකිරීම් ක්‍රමවේදය හැදෑරීමට වඩාත් සුදුසු මූලාශ්‍ර වර්ගය කුමක්ද?", "පුරාවිද්‍යාත්මක නටබුන් හා ථූපවංශය වැනි සාහිත්‍ය මූලාශ්‍ර දෙකම", "හටන් කාව්‍ය පමණක්", "කාසි පමණක්", "ග්‍රීක සිතියම් පමණක්", "සාහිත්‍ය විස්තර හා ස්ථානීය පුරාවිද්‍යා පරීක්ෂණ එක් කිරීමෙන් නිවැරදි තොරතුරු ලැබේ."),
    q(T, "පුරාවිද්‍යා කැණීම්වලදී හමුවන මැටි බඳුන් කැබලි (Pottery sherds) ඉතිහාසඥයන්ට වැදගත් වන්නේ ඇයි?", "විවිධ සංස්කෘතික ස්ථරවල කාලය හා විදේශ වෙළෙඳ සබඳතා හඳුනා ගැනීමට", "රජවරුන්ගේ නම් මැටි බඳුන්වල ලියා ඇති බැවින්", "මැටි බඳුන් රත්‍රන්වලින් සාදා ඇති බැවින්", "ඒවා යුද ආයුධ ලෙස භාවිත කළ බැවින්", "කළු-රතු මැටි බඳුන්, රෝම රුලෙට් මැටි බඳුන් හා චීන පෝසිලේන් මගින් කාලය හා වෙළෙඳාම හඳුනාගනී."),
    q(T, "මන්නාරම ආසන්න මාන්තොට (මහාතිත්ථ) කැණීම්වලින් විශාල වශයෙන් හමු වූ ඉස්ලාමීය හා චීන මැටි බඳුන්වලින් ඔප්පු වන්නේ කුමක්ද?", "මාන්තොට පැරණි අන්තර්ජාතික වෙළෙඳ වරායක්ව පැවති බව", "චීන හමුදා මන්නාරමේ කඳවුරු බැඳ සිටි බව", "මැටි කර්මාන්තය මන්නාරමේ තහනම් වූ බව", "පෘතුගීසීන් මාන්තොට පිහිටුවූ බව", "මහාතිත්ථ පෙරදිග හා අපරදිග සම්බන්ධ කළ ප්‍රධාන වරාය විය."),
    q(T, "ශ්‍රී ලංකාවේ බටහිර වෙරළේ හා වෙල්ගම් වෙහෙරෙන් හමු වූ පැරණි දෙමළ සෙල්ලිපි මගින් කුමක් සනාථ වේද?", "විවිධ ජන කොටස් අතර පැවති සංස්කෘතික හා ආගමික සබඳතා", "මධ්‍යශිලා යුගයේ ගල් ආයුධ නිපදවීම", "පෘතුගීසි පාලනය", "බ්‍රිතාන්‍ය දුම්රිය සේවය", "වෙල්ගම් වෙහෙර (රාජරාජපෙරුම්පල්ලි) ආදී තැන්වල දෙමළ බෞද්ධ සෙල්ලිපි හමුවී ඇත."),
    q(T, "ප්‍රාග් ඓතිහාසික මිනිසා ඇඳුම් වෙනුවට භාවිත කරන්නට ඇතැයි සැලකෙන්නේ මොනවාද?", "සත්ත්ව සම් හා ගස්වල පට්ටා (රිටි ගස් පට්ටා)", "කපු රෙදි", "සේද සළු", "පොලියෙස්ටර් රෙදි", "ගස් පට්ටා හා සත්ත්ව සම් ශීතලෙන් හා පරිසරයෙන් ආරක්ෂා වීමට භාවිත කෙරිණි."),
    q(T, "රිටි පට්ටා හා සත්ත්ව සම් සැකසීම සඳහා බලංගොඩ මානවයා භාවිත කළ ගල් ආයුධ විශේෂය කුමක්ද?", "සීරුම් ගල් (Scrapers) සහ විදුම් කටු (Borers)", "කැටපෝල", "තඹ පිහි", "යකඩ කතුරු", "සත්ත්ව සම් හා ලී සීරීමටත් සිදුරු කිරීමටත් විශේෂිත ගල් ආයුධ භාවිත කර ඇත."),
    q(T, "බෙල්ලන්බැඳි පැලැස්ස ආදී තැන්වලින් හමු වූ ගල් අවශේෂ අතර 'ඇඹරුම් ගල්' තිබීමෙන් කුමක් පැහැදිලි වේද?", "ඇට වර්ග හා ආහාර කුඩු කර පිළියෙල කර ගැනීමට දැන සිටි බව", "ගෙවල් සෑදීමට සිමෙන්ති ඇඹරූ බව", "මැණික් කැපීමේ කර්මාන්තශාලා තිබූ බව", "රන් කුඩු කළ බව", "වියළි ධාන්‍ය හා ගෙඩි වර්ග තලා ආහාරයට ගැනීමට කළුගල් ඇඹරුම් ගල් යොදාගෙන ඇත."),
    q(T, "ඉතිහාසය හැදෑරීමේදී පුරාවිද්‍යාත්මක මූලාශ්‍රවල ඇති ප්‍රධාන වාසිය කුමක්ද?", "රචකයාගේ පක්ෂග්‍රාහී අදහස්වලින් තොර වීම", "සෑම රජෙකුගේම පෞද්ගලික සිතිවිලි විස්තර කිරීම", "ඉතා සරල කතන්දර ආකාරයෙන් තිබීම", "පමණක් විදේශිකයන් විසින් නිර්මාණය කර තිබීම", "පුරාවිද්‍යා මූලාශ්‍ර භෞතික සාධක වන බැවින් අතිශයෝක්තියෙන් තොර සමකාලීන සාක්ෂි සපයයි."),
    q(T, "වංශකතාවල තොරතුරු අධ්‍යයනය කිරීමේදී ඉතිහාසඥයන් ප්‍රවේශම් විය යුත්තේ ඇයි?", "කතුවරයාගේ ආගමික හා රාජකීය පක්ෂග්‍රාහීත්වය සහ අතිශයෝක්ති තිබිය හැකි බැවින්", "ඒවා කිසිදු සත්‍යයක් නැති මනඃකල්පිත කතා වන බැවින්", "ඒවා විදේශීය භාෂාවලින් ලියා ඇති බැවින්", "ඒවායේ කාලවකවානු සඳහන් නොවන බැවින්", "රජවරුන්ගේ අඩුපාඩු වසා ගුණ වර්ණනා වැඩි කිරීම වැනි පක්ෂග්‍රාහීත්වයන් විමසිල්ලෙන් පරීක්ෂා කළ යුතුය."),
    q(T, "පුරාවිද්‍යාත්මක මූලාශ්‍ර කොටස් වශයෙන් වර්ග කිරීමේදී 'ස්මාරක' ගණයට අයත් වන්නේ මොනවාද?", "දාගැබ්, පිළිමගෙවල්, වාපි කර්මාන්ත හා මාලිගා නටබුන්", "තඹ සන්නස් පමණක්", "කහපණ කාසි පමණක්", "දීපවංශය හා මහාවංශය", "විශාල ඉදිකිරීම් හා ගෘහ නිර්මාණ නටබුන් පුරාවිද්‍යාත්මක ස්මාරක ලෙස සැලකේ."),
    q(T, "රන්, රිදී, තඹ හෝ පිත්තලවලින් නිමැවුණු ආගමික ප්‍රතිමා හා උපකරණ අයත් වන්නේ කුමන මූලාශ්‍ර කොටසටද?", "පුරාවස්තු (Artifacts)", "සාහිත්‍ය මූලාශ්‍ර", "විදේශ වාර්තා", "ජනශ්‍රැති", "පුරාණ මානවයා නිර්මාණය කළ චලනය කළ හැකි භෞතික ද්‍රව්‍ය පුරාවස්තු ලෙස හැඳින්වේ."),
    q(T, "අභිලේඛන ඒවා ලියා ඇති මාධ්‍යය අනුව වර්ග කළ විට 'ටැම් ලිපියක්' යනු කුමක්ද?", "සකස් කළ ශෛලමය කුළුණක් මත කොටන ලද ලිපියකි", "ගල් පර්වතයක මුහුණත කොටන ලද ලිපියකි", "ලෙන් කටාරමක කොටන ලද ලිපියකි", "තඹ පතක කොටන ලද ලිපියකි", "ගල් කණුවක් (ටැඹක්) මත කොටා පොදු ස්ථානවල සිටුවන ලද ලිපි ටැම් ලිපි නම් වේ."),
    q(T, "මහා පරාක්‍රමබාහු රජු විසින් බුරුමයේ (රාමඤ්ඤ දේශයේ) ආක්‍රමණය ගැන සඳහන් කරන සෙල්ලිපිය කුමක්ද?", "දේවනගල සෙල්ලිපිය", "ගල්පොත ලිපිය", "වේවැල්කැටිය ලිපිය", "තෝණිගල ලිපිය", "මාවනැල්ල අසල දේවනගල ගිරි ලිපිය කිත්ති සෙනෙවියා බුරුම ආක්‍රමණයට ගිය බව තහවුරු කරයි."),
    q(T, "මහනුවර යුගයේ රජවරුන් විසින් විහාර හා පුද්ගලයන් වෙත ඉඩම් ප්‍රදානය කිරීමේදී බහුලව භාවිත කළ ලේඛන විශේෂය කුමක්ද?", "තඹ සන්නස් හා තුඩපත්", "පූර්ව බ්‍රාහ්මී ලෙන් ලිපි", "රෝම සිතියම්", "ගඩොල් ලිපි", "මහනුවර සමයේ රාජකීය ඉඩම් ප්‍රදාන සඳහා තඹ සන්නස් හා ලේකම්ගේ අත්සනින් තුඩපත් නිකුත් කෙරිණි."),
    q(T, "ශ්‍රී ලංකාවේ පැරණිතම ගල් ලෙන් වාසස්ථාන කැණීම්වලදී 'මල් හා පැළෑටි පරාග' අධ්‍යයනය කිරීමෙන් දැනගත හැක්කේ කුමක්ද?", "පුරාණ දේශගුණය හා පැවති වෘක්ෂලතා ස්වභාවය", "රජවරුන්ගේ ආගම", "කාසිවල වටිනාකම", "යුද සේනා ප්‍රමාණය", "පුරා පාරිසරික විද්‍යාව තුළ පරාග අධ්‍යයනයෙන් එදා පැවති වනාන්තර හා දේශගුණය හෙළි වේ."),
    q(T, "හෝර්ටන්තැන්නේ පුරාවිද්‍යා කැණීම්වලින් ක්‍රි.පූ. 13,000 තරම් ඈත කාලයේ හමු වූ සුවිශේෂී සාධකය කුමක්ද?", "ඕට්ස් හා බාර්ලි වැනි ධාන්‍ය පරාග සහ ගිනි තැබූ පස් ස්තර", "රෝම රන් කාසි", "පෘතුගීසි කාලතුවක්කු", "මහාවංශයේ පුස්කොළ පිටපත්", "මධ්‍යම කඳුකරයේ හෝර්ටන්තැන්නෙන් ආරම්භක කෘෂි කළමනාකරණ සංඥා හමු වී ඇත."),
    q(T, "මානව පරිණාමයේදී ගල් ආයුධ විශාල රළු ආයුධවල සිට කුඩා සියුම් ආයුධ බවට පත්වූයේ කුමන හේතුවක් නිසාද?", "ලී මිටවලට සවි කර දුනු-ඊතල හා හෙල්ල ලෙස කාර්යක්ෂමව භාවිත කිරීමට", "ගල් හිඟ වීම නිසා", "ළමුන්ට සෙල්ලම් කිරීමට", "ලෝහ ආයුධ ආදේශ කිරීමට", "ක්ෂුද්‍ර ශිලා ආයුධ ලී හෝ ඇටකටු මිටවල රඳවා සංයුක්ත ආයුධ ලෙස භාවිත කළේය."),
    q(T, "ප්‍රාග් ඓතිහාසික මිනිසුන් ජල ප්‍රවාහ සහ ලෙන් සමීපයේ කඳවුරු බැඳීමට ප්‍රධාන හේතුව කුමක් වීද?", "පානීය ජලය, දඩයම් සතුන් හා වර්ෂාවෙන් ආරක්ෂාව පහසුවෙන් ලැබීම", "වෙළෙඳ නැව් පැමිණීම බලාපොරොත්තුවෙන්", "විශාල වැව් කැණීමට", "රජ මාලිගා තැනීමට", "ජල මූලාශ්‍ර අසල සතුන් ගැවසීමත් ලෙන් මගින් ස්වාභාවික ආවරණය ලැබීමත් මීට හේතු විය."),
    q(T, "ලංකාවේ ප්‍රාග් ඓතිහාසික සාධක විද්‍යාත්මකව ගවේෂණය කිරීම ආරම්භ කළ පුරෝගාමී ශ්‍රී ලාංකික විද්වතා කවුද?", "ආචාර්ය පී.ඊ.පී. දැරණියගල", "රොබට් නොක්ස්", "සර් විලියම් ග්‍රෙගරි", "විල්හෙල්ම් ගයිගර්", "ආචාර්ය පී.ඊ.පී. දැරණියගල මහතා බලංගොඩ මානවයා සහ රත්නපුර පාෂාණිභූත සත්ත්ව සංහතිය ගවේෂණය කළේය."),
    q(T, "පුරාවිද්‍යාත්මක කැණීම්වලින් බලංගොඩ මානවයාගේ අධ්‍යයනය තවදුරටත් පුළුල් කළ කීර්තිමත් පුරාවිද්‍යාඥයා කවුද?", "ආචාර්ය ශිරාන් දැරණියගල", "මහාචාර්ය හේමචන්ද්‍ර රායි", "ජේ.ඊ. ටෙනන්ට්", "එච්.සී.පී. බෙල්", "ආචාර්ය ශිරාන් දැරණියගල මහතා පාහියන්ගල, බටදොඹලෙන, අනුරාධපුර ඇතුළුනුවර ඇතුළු විද්‍යාත්මක කැණීම් මෙහෙයවීය."),
    q(T, "මෙගලිතික සංස්කෘතියේදී 'මෙගලිතික' යන වචනයේ අර්ථය කුමක්ද?", "විශාල ගල් (Megalith)", "කුඩා කාසි", "තඹ පුවරු", "මැටි පහන්", "Megas (විශාල) සහ Lithos (ගල) යන ග්‍රීක වචන ඇසුරෙන් විශාල ගල් පුවරු සුසාන සඳහා එම නම යෙදේ."),
    q(T, "ඉබ්බන්කටුව මෙගලිතික සුසානයෙන් හමු වූ ආභරණ අතර විදේශීය වෙළෙඳ සබඳතා හඟවන වටිනා ගල් වර්ගය කුමක්ද?", "කානේලියන් (Carnelian) හා ඇගේට් පබළු", "දියමන්ති ඔටුනු", "රබර් මුදු", "ප්ලාස්ටික් පබළු", "ඉබ්බන්කටුවෙන් හමු වූ කානේලියන් පබළු ඉන්දියාවේ ගුජරාට් ප්‍රදේශය සමඟ තිබූ සබඳතා පෙන්වයි."),
    q(T, "පූර්ව ඓතිහාසික යුගයේ ජනතාව යකඩ තාක්ෂණය ප්‍රගුණ කර සිටීමෙන් රටේ සංවර්ධනයට සිදු වූ ප්‍රධාන බලපෑම කුමක්ද?", "ගන වනාන්තර එළි පෙහෙළි කර කෘෂිකර්මාන්තය හා වාරි කටයුතු පුළුල් කිරීම", "සියලු ජනයා මුහුදු යාම නතර කිරීම", "කාසි භාවිතය අත්හැරීම", "ගල් ලෙන් තුළට සීමා වීම", "ශක්තිමත් යකඩ උපකරණ නිසා ගොවිතැන හා වැව් ඉදිකිරීම වේගවත් විය."),
    q(T, "සාහිත්‍ය මූලාශ්‍ර අතර 'සද්ධර්මාලංකාරය' හා 'සද්ධර්මරත්නාවලිය' වැනි ධර්ම කථා ග්‍රන්ථ ඉතිහාසය හැදෑරීමට උපකාරී වන්නේ කෙසේද?", "එදා සාමාන්‍ය ජන ජීවිතය, සමාජ සිරිත් විරිත් හා භාෂාව පිළිබිඹු කරන බැවින්", "රාජ්‍ය යුද ගිවිසුම් ඇතුළත් බැවින්", "විදේශීය සිතියම් ඇති බැවින්", "ලන්දේසි නීති අඩංගු බැවින්", "ධර්ම කථා තුළ ලංකාවේ ගැමි ජීවිතය, වෘත්තීන් හා උපමා ඇසුරෙන් සමාජ තත්ත්වය හෙළි වේ."),
    q(T, "මහාවංශය ජර්මානු හා ඉංග්‍රීසි භාෂාවට පරිවර්තනය කරමින් එහි අන්තර්ජාතික වටිනාකම පෙන්වා දුන් විද්වතා කවුද?", "මහාචාර්ය විල්හෙල්ම් ගයිගර්", "ජෝර්ජ් ටර්නර්", "මාකෝ පෝලෝ", "වැස්කෝ ද ගාමා", "ජර්මානු ජාතික මහාචාර්ය විල්හෙල්ම් ගයිගර් මහාවංශය හා චූලවංශය විද්‍යාත්මකව සංස්කරණය කර පරිවර්තනය කළේය."),
    q(T, "1837 දී මහාවංශයේ මුල් කොටස ඉංග්‍රීසියට පරිවර්තනය කර ප්‍රකාශයට පත් කළ බ්‍රිතාන්‍ය සිවිල් සේවකයා කවුද?", "ජෝර්ජ් ටර්නර්", "ජෝන් ඩොයිලි", "ෆ්‍රෙඩ්රික් නෝර්ත්", "විලියම් කෝල්බෲක්", "ජෝර්ජ් ටර්නර්ගේ පරිවර්තනය ඉන්දීය හා ශ්‍රී ලංකා ඉතිහාසයේ අශෝක අධිරාජ්‍යය හඳුනා ගැනීමට පවා උදව් විය."),
    q(T, "මිහිඳු හිමි වැඩමවීමට පෙර සිටම ලංකාවේ දේවාල හා නක්ෂත්‍ර කටයුතු පැවති බව සඳහන් වන වංශකතාව කුමක්ද?", "මහාවංශය", "රාජරත්නාකරය", "සීතාවක හටන", "දඹදෙණි අස්න", "මහාවංශයේ 10 වන පරිච්ඡේදයේ පණ්ඩුකාභය රජු කාලයේ යක්ෂ, නිඝණ්ඨ හා බ්‍රාහ්මණ ආගමික ස්ථාන ගැන කියැවේ."),
    q(T, "මහාබෝධිවංශය නම් වංශකතාව රචනා වී ඇත්තේ කුමන භාෂාවකින් හා කුමන ප්‍රධාන තේමාව යටතේද?", "පාලි භාෂාවෙන් - ජය ශ්‍රී මහා බෝධීන් වහන්සේගේ ඉතිහාසය", "සංස්කෘත භාෂාවෙන් - සීගිරි ඉතිහාසය", "දෙමළ භාෂාවෙන් - යාපනය ඉතිහාසය", "ලතින් භාෂාවෙන් - රෝම වෙළෙඳාම", "උපතිස්ස හිමි විසින් රචිත පාලි මහාබෝධිවංශය ශ්‍රී මහා බෝධිය හා බෝධි වන්දනාව විස්තර කරයි."),
    q(T, "ශ්‍රී ලංකාවේ පැරණිම ව්‍යාකරණ ග්‍රන්ථය වන 'සිදත් සඟරාව' ඓතිහාසික මූලාශ්‍රයක් ලෙස වැදගත් වන්නේ කුමන යුගයක තොරතුරු සඳහාද?", "දඹදෙණි යුගයේ භාෂාව හා විද්වත් සංස්කෘතිය", "සීතාවක යුද්ධ", "ලන්දේසි පාලනය", "බ්‍රිතාන්‍ය ආර්ථිකය", "දඹදෙණි යුගයේ පතිරාජ පිරිවෙන්පති හිමියන් විසින් සිදත් සඟරාව රචනා කරන ලදී."),
    q(T, "කුරුණෑගල හා ගම්පොළ අවධිවල සිටි ඇතැම් ආගමික හා සමාජ තොරතුරු ඇතුළත් 'සද්ධර්මරත්නාකරය' රචනා කළ හිමිනම කවුද?", "විමලකීර්ති හිමි", "මහානාම හිමි", "තොටගමුවේ ශ්‍රී රාහුල හිමි", "වෑත්තෑවේ හිමි", "දෙවන විමලකීර්ති හිමි විසින් කෝට්ටේ මුල් අවධියේ සද්ධර්මරත්නාකරය සම්පාදනය කරන ලදී."),
    q(T, "ඉතිහාසය අධ්‍යයනයේදී 'විදේශීය වාර්තා' වල ඇති ප්‍රධාන දුර්වලතාවක් ලෙස සැලකිය හැක්කේ කුමක්ද?", "දේශීය භාෂාව හා සංස්කෘතිය නිසි ලෙස නොදැන වැරදි අර්ථකථන දීමට ඉඩ තිබීම", "ලංකාවට කිසිදා විදේශිකයන් නොපැමිණීම", "ඒවා සියල්ල ගල් මත කොටා තිබීම", "ඒවායේ දින වකවානු නැති වීම", "ඇතැම් විදේශීය ලේඛකයන් තමා ඇසූ දේ මත හෝ පරිවර්තන දෝෂ මත තොරතුරු අතිශයෝක්තියෙන් ලියා ඇත."),
    q(T, "චීන සංචාරක මා හුආන් (Ma Huan) සහ ෂෙං හෝ (Zheng He) ගේ ගවේෂණ වාර්තා වැදගත් වන්නේ කුමන යුගයේ ලංකා ඉතිහාසයටද?", "කෝට්ටේ යුගයේ ආරම්භක සමය", "ප්‍රාග් ඓතිහාසික යුගය", "පොළොන්නරු යුගයේ ආරම්භය", "ලන්දේසි යුගයේ අවසානය", "15 වන සියවසේ මුල් කාලයේ චීන නාවික සෙනෙවි ෂෙං හෝගේ ගමන් හා ගාල්ල ත්‍රිභාෂා ලිපිය ඉතා වැදගත්ය."),
    q(T, "ගාල්ලෙන් හමු වූ 1411 වසරට අයත් ත්‍රිභාෂා සෙල්ලිපිය කොටා ඇති භාෂා තුන මොනවාද?", "චීන, දෙමළ හා පර්සියානු", "සිංහල, පාලි හා සංස්කෘත", "පෘතුගීසි, ලන්දේසි හා ඉංග්‍රීසි", "ග්‍රීක, ලතින් හා අරාබි", "ෂෙං හෝ සෙනෙවියා විසින් ශ්‍රී පාදය, හින්දු කෝවිලක් හා අල්ලාහ් වෙනුවෙන් පිදූ පූජා මෙම ත්‍රිභාෂා ලිපියේ දැක්වේ."),
    q(T, "සාහිත්‍ය මූලාශ්‍රවල අඩංගු 'ප්‍රශස්ති කාව්‍ය' වඩාත් ප්‍රචලිත වූයේ කුමන යුගයේද?", "මහනුවර යුගයේදී", "අනුරාධපුර මුල් යුගයේදී", "මධ්‍යශිලා යුගයේදී", "පොළොන්නරු යුගයේදී", "දෙවන රාජසිංහ හා ශ්‍රී වීර පරාක්‍රම නරේන්ද්‍රසිංහ වැනි උඩරට රජවරුන් වර්ණනා කරමින් ප්‍රශස්ති රචනා විය."),
    q(T, "ශ්‍රී ලංකාවේ බටහිර වෙරළේ 'මන්නාරම' හා 'උරුමලෙයි' ප්‍රදේශවලින් හමු වූ මුතු කිමිදීම හා බැඳුණු පුරාවිද්‍යා සාධක මොනවාද?", "මුතු බෙල්ලන් කටු ගොඩගැසීම් හා රෝම/අරාබි වෙළෙඳ කාසි", "පිහිනුම් තටාක", "බ්‍රිතාන්‍ය දුම්රිය", "කාර්මික විප්ලවයේ යන්ත්‍ර", "මන්නාරම් බොක්ක අනුරාධපුර යුගයේ සිටම උසස් මුතු සපයන ලෝක ප්‍රකට ස්ථානයක් විය."),
    q(T, "අපර බ්‍රාහ්මී හෙවත් ක්‍රි.ව. 1-4 සියවස්වල සෙල්ලිපි පූර්ව බ්‍රාහ්මී ලිපිවලින් වෙනස් වන ප්‍රධාන ලක්ෂණය කුමක්ද?", "ලෙන් ලිපි වෙනුවට ගිරි ලිපි හා වාරි කර්මාන්ත/බදු ප්‍රදාන ගැන වැඩි වශයෙන් සඳහන් වීම", "දෙමළ භාෂාව පමණක් භාවිත කිරීම", "පෘතුගීසි වචන යොදා ගැනීම", "කඩදාසි මත ලිවීම", "පසුකාලීනව වැව්, ඇළ මාර්ග හා කුඹුරු ආදායම් විහාරස්ථානවලට පිදීම පර්වත බිත්තිවල ලියැවිණි."),
    q(T, "කැලණිය, අකුරැස්ස වැනි තෙත් කලාපීය ප්‍රදේශවලත් අනුරාධපුර යුගයේ මුල් කාලීන ජනාවාස පැවති බව තහවුරු වන්නේ කුමන මූලාශ්‍රවලින්ද?", "කැණීම්වලින් හමු වූ කළු-රතු මැටි බඳුන් හා පැරණි ලෙන් ලිපිවලින්", "ලන්දේසි සංගණන වාර්තාවලින්", "බ්‍රිතාන්‍ය වතු ගිණුම්වලින්", "පාහියන් හිමිගේ සටහන්වලින් පමණක්", "දකුණු හා බටහිර තෙත් කලාපයේද පූර්ව බ්‍රාහ්මී ලිපි හා මූල ඓතිහාසික මැටි බඳුන් හමුවේ."),
    q(T, "පුරාවිද්‍යාත්මක කැණීම්වලදී 'ස්තර වින්‍යාසය' (Stratigraphy) වැදගත් වන්නේ ඇයි?", "පසේ යටි ස්තර පැරණි බව හා උඩු ස්තර නවීන බව අනුපිළිවෙළින් හඳුනා ගැනීමට", "පසේ වර්ණය අලංකාර කිරීමට", "ජලය පොළොවට උරා ගැනීමට", "වගා කටයුතු පහසු කිරීමට", "භූමියේ තැන්පත් වී ඇති පස් ස්තරවල සාපේක්ෂ කාලානුක්‍රමය හඳුනා ගැනීමට ස්තර වින්‍යාසය යොදා ගනී."),
    q(T, "කලා ඔය නිම්නයේ පිහිටි පොම්පරිප්පුවට අමතරව යකඩ යුගයේ බරණි සුසාන හමු වූ තවත් ස්ථානයක් කුමක්ද?", "පිංවැව ගල්සොහොන්කනත්ත හා කරඹන්කුලම", "මහනුවර වැව රවුම", "ගාලු වරාය", "කොළඹ බේරේ වැව", "අනුරාධපුර හා පුත්තලම අතර ප්‍රදේශවල බරණි හා මෙගලිතික සුසාන රැසක් සොයාගෙන ඇත."),
    q(T, "මෙගලිතික සුසාන භූමියක් වන 'යටිගල්පොත්ත' හා 'පිංවැව' යන ස්ථානවල කැණීම්වලින් පෙන්නුම් කරන සමාජ ලක්ෂණය කුමක්ද?", "විධිමත් අවමංගල්‍ය චාරිත්‍ර හා පරලොව ජීවිතය පිළිබඳ විශ්වාස පැවති බව", "මළවුන් ගැන කිසිදු සැලකිල්ලක් නොතිබූ බව", "මුහුදු කොල්ලකරුවන් විසූ බව", "සතුන් පමණක් වැළලූ බව", "මළවුන් සමඟ මැටි බඳුන්, ආභරණ හා ආයුධ තැන්පත් කිරීම පරලොව විශ්වාසයක් තිබූ බව පෙන්වයි."),
    q(T, "මාතලේ අළුවිහාරය අනුරාධපුර යුගයේ සාහිත්‍ය ඉතිහාසයේ සුවිශේෂී ස්ථානයක් වන්නේ ඇයි?", "ත්‍රිපිටක ධර්මය ප්‍රථම වරට පුස්කොළ පොත්වල ග්‍රන්ථාරූඪ කළ ස්ථානය වන බැවින්", "මහාවංශය මුද්‍රණය කළ ස්ථානය වන බැවින්", "ප්‍රථම පාසල පිහිටුවූ බැවින්", "පෘතුගීසීන් සමඟ ගිවිසුම අත්සන් කළ බැවින්", "වළගම්බා රජ සමයේ මාතලේ අළුවිහාරයේදී ත්‍රිපිටකය පුස්කොළවල ලියා තැබිණි."),
    q(T, "පුස්කොළ පොත් සැකසීම සඳහා පැරණි ලංකාවේ බහුලව භාවිත කළ ශාක පත්‍රය කුමක්ද?", "තල ගසේ ගොබය (තල කොළ)", "පොල් අතු", "කෙසෙල් කොළ", "තේ දළු", "සැකසූ තල කොළ මත පන්හිඳෙන් ලියා කළුමැදීමෙන් පුස්කොළ පොත් සකසන ලදී."),
    q(T, "ශ්‍රී ලංකාවේ ප්‍රාග් ඓතිහාසික කාලයේ මානවයා සමඟ ජීවත් වූ සුලභ ආහාරයට ගත් ගොළුබෙලි විශේෂයක් වන්නේ කුමක්ද?", "ඇකවුස් (Acavus) ගොළුබෙල්ලන් හා පලාතුමා (Paludomus)", "සිප්පි කටු පමණක්", "ඉස්සන් පමණක්", "මුහුදු කැස්බෑවන් පමණක්", "පාහියන්ගල හා බටදොඹලෙන කැණීම්වලින් දහස් ගණනින් ඇකවුස් ගස් ගොළුබෙලි කටු හමුවේ."),
    q(T, "ප්‍රාග් ඓතිහාසික මිනිසුන් සත්ත්ව ඇටකටු (අස්ථි) ආයුධ නිපදවීමටද යොදා ගත් බවට සාධක මොනවාද?", "උල් කළ මුව අං සහ වඳුරු ඇටකටුවලින් තැනූ ඉඳිකටු හා ඇණ", "ඇත්දළ මාලිගා", "මෝර දත් කඩු", "ගව ඇටවලින් කළ රෝද", "බෙල්ලන්බැඳි පැලැස්සෙන් හා බටදොඹලෙනින් ඇටකටු උල් හා මෙවලම් හමු වී ඇත."),
    q(T, "සෙල්ලිපියක් ස්ථානයෙන් පිටතට ගෙන නොගොස් කඩදාසි මත පිටපත් කර ගැනීමේ පුරාවිද්‍යා ක්‍රමය හඳුන්වන්නේ කුමන නමකින්ද?", "ස්පර්ශ ලාංඡන ක්‍රමය (Estampage)", "කාබන් 14 පරීක්ෂාව", "ඡායාරූප විකාශනය", "ලේසර් කැපීම", "තෙත් කළ විශේෂ කඩදාසියක් සෙල්ලිපිය මත අලවා තීන්ත ආලේප කර අකුරු පිටපත් කිරීම Estampage නම් වේ."),
    q(T, "ශ්‍රී ලංකාවේ පැරණි රාජ්‍ය වර්ෂ ගණනය කිරීම සඳහා ප්‍රධාන වශයෙන් යොදා ගත් යුග ක්‍රම දෙක මොනවාද?", "බුද්ධ වර්ෂ ක්‍රමය සහ ශක වර්ෂ ක්‍රමය", "ක්‍රිස්තු වර්ෂ සහ හිජ්රි වර්ෂ", "වික්‍රම වර්ෂ සහ චීන වර්ෂ", "ග්‍රෙගෝරියන් සහ ජූලියන් වර්ෂ", "පැරණි ශිලා ලේඛන හා වංශකතාවල බුද්ධ වර්ෂ හා ශක වර්ෂ ක්‍රම බහුලව භාවිත විය."),
    q(T, "ක්‍රි.ව. 1 වන සියවසේ රචිත 'පෙරිප්ලස් ඔෆ් ද එරිත්‍රියන් සී' නම් නාවික අත්පොතෙහි ලංකාව ගැන දැක්වෙන කරුණු මොනවාද?", "මුතු, මැණික්, සිහින් මස්ලින් රෙදි හා කැස්බෑ කටු වෙළෙඳාම", "කෝපි හා තේ වගාව", "ලන්දේසි කුරුඳු ඒකාධිකාරය", "මහනුවර ඇසළ පෙරහැර", "මධ්‍යධරණී හා ඉන්දියානු සාගර වෙළෙඳාම විස්තර කළ එරිත්‍රියන් මුහුදේ නාවික සටහන්වල ලංකාව 'පලයිසිමුන්ඩු' ලෙස දැක්වේ."),
    q(T, "ප්‍රාග් ඓතිහාසික මිනිසුන්ගේ ශාරීරික ස්වරූපය හා චර්යාවන් සමඟ සමානකම් දක්වන බව මානව විද්‍යාඥයන් පෙන්වා දෙන මෙරට ආදිවාසී ජන කොටස කවුද?", "වැදි ජනතාව (ආදිවාසීන්)", "පෘතුගීසි බර්ගර්වරු", "මැලේ ජාතිකයන්", "කාපිරි ජනතාව", "ජාන විද්‍යාත්මක හා මානව විද්‍යාත්මක අධ්‍යයන අනුව බලංගොඩ මානවයා සහ ආදිවාසී වැදි ජනයා අතර ළඟ සබඳතාවක් පෙනේ."),
    q(T, "කන්දරෝදෙයි (කදුරුගොඩ - යාපනය) කැණීම්වලින් හමු වූ කුඩා ස්තූප සමූහය හා කළු-රතු මැටි බඳුන්වලින් හෙළි වන්නේ කුමක්ද?", "මූල ඓතිහාසික හා අනුරාධපුර මුල් යුගයේ සිට උතුරු ප්‍රදේශය බෞද්ධ හා ජනාවාස මධ්‍යස්ථානයක් වූ බව", "යාපනය කිසිදා ජනාවාස නොතිබූ බව", "එහි පෘතුගීසි පල්ලියක් පමණක් තිබූ බව", "එය 19 වන සියවසේ නගරයක් බව", "කන්දරෝදෙයි කැණීම් උතුරු ලංකාවේ ප්‍රාග් හා මුල් ඓතිහාසික සංස්කෘතික සම්බන්ධතා තහවුරු කරයි."),
    q(T, "පැරණි ශිලා ලේඛනවල දක්නට ලැබෙන 'බ්‍රාහ්මී' අක්ෂර ලංකාවට හඳුන්වා දීමත් සමඟ සිදු වූ සුවිශේෂී වෙනස කුමක්ද?", "රාජ්‍ය පාලන තොරතුරු, දානමාන හා සංස්කෘතික කරුණු ස්ථිරව සටහන් වීම ඇරඹීම", "දඩයම සම්පූර්ණයෙන් නතර වීම", "සියලු වැව් අත්හැර දැමීම", "සංස්කෘත භාෂාව අහෝසි වීම", "ලේඛන කලාව ව්‍යාප්ත වීමත් සමඟ ඉතිහාසය හා සාහිත්‍යය වේගයෙන් වර්ධනය විය."),
    q(T, "ශ්‍රී ලංකාවේ පැරණිතම මුද්‍රා තැබූ නැතහොත් අක්ෂර කෙටූ කාසි ලෙස හඳුනාගෙන ඇති මුල්ම කාසි කුමන ප්‍රමාණවලින් යුක්ත වීද?", "රිදී හා තඹ කහපණ කාසි", "ප්ලැටිනම් කාසි", "නිකල් කාසි", "කඩදාසි මුදල් නෝට්ටු", "අනුරාධපුර ඇතුළුනුවරින් හා තිස්සමහාරාමයෙන් ක්‍රි.පූ. 3-2 සියවස්වල රිදී කහපණ හමු වී තිබේ."),
    q(T, "විජය කුමරු පැමිණීමට පෙර ලංකාවේ විසූ 'යක්ෂ' සහ 'නාග' යනු කවුරුන් ලෙස නූතන ඉතිහාසඥයන් හඳුනාගන්නේද?", "විවිධ වෘත්තීය හා ගෝත්‍රික සංස්කෘතික ජන කොටස්", "මිනිසුන් නොවන අදෘශ්‍යමාන භූතයන්", "පිටසක්වළ ජීවීන්", "යුරෝපීය වෙළෙඳුන්", "මහාවංශයේ සඳහන් යක්ෂ හා නාග ගෝත්‍ර යනු මෙරට ස්වදේශික මූල ඓතිහාසික ජන කොටස් බව පිළිගැනේ."),
    q(T, "මහාවංශයට අනුව විජය කුමරු ලංකාවට ගොඩබසින විටත් කුවේණිය සිදු කරමින් සිටි කර්මාන්තය කුමක්ද?", "කපු කටිමින් සිටීම", "යකඩ උණු කරමින් සිටීම", "මැටි වළං සාදමින් සිටීම", "වැවක් බඳිමින් සිටීම", "කුවේණිය කපු කටිමින් සිටීම මගින් එවකට මෙරට ජනයා රෙදිපිළි කර්මාන්තය දැන සිටි බව ගම්‍ය වේ."),
    q(T, "අපර බ්‍රාහ්මී යුගයේ ශිලා ලේඛන කියවීමේදී පැරණි ලංකාවේ වැව්වල නම් සමඟ බහුලව යෙදුණු වචනය කුමක්ද?", "වපි (වැව)", "සාගරය", "තටාකය", "සමුද්‍රය", "'වපි' හෙවත් 'වැවි' යන පදය මුල් යුගයේ වැව් හැඳින්වීමට බ්‍රාහ්මී ලිපිවල බහුලව භාවිත විය."),
    q(T, "පුරාවිද්‍යාත්මක ක්ෂේත්‍රයේදී 'පුරාවිද්‍යා දෙපාර්තමේන්තුව' ප්‍රථම වරට පිහිටුවන ලද්දේ කවදාද?", "1890 දී (එච්.සී.පී. බෙල්ගේ ප්‍රධානත්වයෙන්)", "1815 දී", "1948 දී", "1972 දී", "1890 දී ආරම්භ කළ පුරාවිද්‍යා සමීක්ෂණ දෙපාර්තමේන්තුවේ පළමු කොමසාරිස්වරයා එච්.සී.පී. බෙල් මහතායි."),
    q(T, "සීගිරිය හා අනුරාධපුර නටබුන් මුල් වරට විද්‍යාත්මකව එළිපෙහෙළි කර වාර්තා කිරීමේ පුරෝගාමියා වූ පළමු පුරාවිද්‍යා කොමසාරිස්වරයා කවුද?", "එච්.සී.පී. බෙල්", "සෙනරත් පරණවිතාන", "සී.ඊ. ගොඩකුඹුර", "රෝලන්ඩ් සිල්වා", "එච්.සී.පී. බෙල් මහතා 1890 සිට 1912 දක්වා අනුරාධපුරය, පොළොන්නරුව හා සීගිරිය කැණීම් වාර්තා කළේය."),
    q(T, "ප්‍රථම ශ්‍රී ලාංකික පුරාවිද්‍යා කොමසාරිස්වරයා ලෙස පත් වී අසමසම සේවයක් ඉටු කළ විද්වතා කවුද?", "මහාචාර්ය සෙනරත් පරණවිතාන", "ආචාර්ය ශිරාන් දැරණියගල", "ආචාර්ය පී.ඊ.පී. දැරණියගල", "මහාචාර්ය සුදර්ශන් සෙනෙවිරත්න", "සෙනරත් පරණවිතාන මහතා 1940 දී පළමු ශ්‍රී ලාංකික පුරාවිද්‍යා කොමසාරිස්වරයා ලෙස පත්විය."),
    q(T, "රෝම අධිරාජ්‍යය සමඟ පැවති වෙළෙඳ සබඳතා පිළිබිඹු කරමින් තිස්සමහාරාමය ආශ්‍රිත අකුරුගොඩ කැණීම්වලින් හමු වූ සුවිශේෂී සාධක මොනවාද?", "පැරණි කර්මාන්තශාලා අවශේෂ, පබළු හා නාම මුද්‍රා සහිත කාසි", "මහනුවර පෙරහැර චිත්‍ර", "බ්‍රිතාන්‍ය මුද්‍රණ යන්ත්‍ර", "සිමෙන්ති පාලම්", "දකුණු ලංකාවේ අකුරුගොඩ මූල ඓතිහාසික සිට අනුරාධපුර මැද යුගය දක්වා දියුණු කර්මාන්ත පුරවරයක් විය."),
    q(T, "ශ්‍රී ලංකාවේ ගල් ලෙන් ප්‍රාග් ඓතිහාසික මානව ජනාවාස අතර 'අළුලෙන' කැණීම සිදු කරන ලද්දේ කුමන ප්‍රදේශයේද?", "කෑගල්ල දිස්ත්‍රික්කයේ අත්තනගොඩ", "මන්නාරම", "මඩකලපුව", "ගාල්ල", "කෑගල්ල අත්තනගොඩ අළුලෙනින්ද බලංගොඩ මානවයාගේ සාධක හමුවී ඇත."),
    q(T, "ගල් යුගය ප්‍රධාන වශයෙන් පුරාශිලා, මධ්‍යශිලා හා නවශිලා යනුවෙන් බෙදන විට ශ්‍රී ලංකාවෙන් බහුලවම සාධක හමුවන්නේ කුමන යුගයටද?", "මධ්‍යශිලා යුගයට (Mesolithic)", "නවශිලා යුගයට පමණක්", "ලෝකඩ යුගයට පමණක්", "කාර්මික යුගයට", "ලංකාවේ ප්‍රාග් ඓතිහාසික අවශේෂවලින් අතිමහත් බහුතරය මධ්‍යශිලා යුගයට අයත් වේ."),
    q(T, "ශ්‍රී ලංකාවේ වෙනම 'තඹ-ලෝකඩ යුගයක්' පැහැදිලිව නොතිබී ගල් යුගයෙන් කෙළින්ම කුමන ලෝහ යුගයට පිවිසි බව පුරාවිද්‍යාඥයන්ගේ මතය වීද?", "යකඩ යුගයට (Iron Age)", "ඇලුමිනියම් යුගයට", "රන් යුගයට", "ටයිටේනියම් යුගයට", "දකුණු ඉන්දියාවේ හා ශ්‍රී ලංකාවේ ප්‍රාග් ඓතිහාසික ජනයා මධ්‍යශිලා යුගයෙන් සෘජුවම මුල් යකඩ යුගයට පිවිසියහ."),
    q(T, "මූල ඓතිහාසික යුගයේ මෙගලිතික සුසානවල තැන්පත් කර තිබී හමුවන යකඩ උපකරණ අතර ප්‍රධාන වශයෙන් දැකිය හැක්කේ මොනවාද?", "හෙල්ල තුඩු, පිහි, දෑකැති හා කෙටේරි", "යුද ටැංකි කොටස්", "බයිසිකල් දම්වැල්", "විදුලි රැහැන්", "කෘෂිකාර්මික හා දඩයම් කටයුතු සඳහා භාවිත කළ යකඩ මෙවලම් සුසානවලින් හමුවේ."),
    q(T, "කුමන සාහිත්‍ය මූලාශ්‍රය තුළ දඹදෙණි යුගයේ චූලවංශ කතුවරයා දෙවන පරාක්‍රමබාහු රජුගේ ශාස්ත්‍රීය හා ආගමික සේවය විස්තර කරයිද?", "චූලවංශයේ පළමු කොටස", "දීපවංශය", "රාජාවලිය", "මන්දාරම් පුවත", "චූලවංශය දෙවන පරාක්‍රමබාහු රජුගේ විද්‍යාත්මක, සාහිත්‍ය හා ශාසනික සේවය දීර්ඝව වර්ණනා කරයි."),
    q(T, "සීගිරි කුරුටු ගී කියවා 'Sigiri Graffiti' නමින් ප්‍රකාශයට පත් කළේ කවුද?", "මහාචාර්ය සෙනරත් පරණවිතාන", "එච්.සී.පී. බෙල්", "ආචාර්ය නන්දදේව විජේසේකර", "මහාචාර්ය සේනක බණ්ඩාරනායක", "මහාචාර්ය පරණවිතාන මහතා සීගිරි කුරුටු ගී 685ක් කියවා ඉංග්‍රීසි පරිවර්තන සහිතව පළ කළේය."),
    q(T, "ශ්‍රී ලංකාවේ පැරණිම නාගරික සැලැස්මක් පිළිබිඹු කරන ක්‍රි.පූ. 4 වන සියවසට පමණ අයත් නගර පාදම හමු වී ඇත්තේ කොතැනින්ද?", "අනුරාධපුර ඇතුළුනුවරින්", "කොළඹ කොටුවෙන්", "ගාලු කොටුවෙන්", "ත්‍රිකුණාමලයෙන්", "ඇතුළුනුවර කැණීම්වලින් ගඩොල් හා ගල් පවුරු සහිත පැරණි නාගරික ලක්ෂණ අනාවරණය වී ඇත."),
    q(T, "චීන ජාතික 'වං තා යුආන්' 14 වන සියවසේ සිය සංචාරක සටහන්වල සඳහන් කළ ලංකාවේ වෙළෙඳ භාණ්ඩ මොනවාද?", "මැණික්, මුතු සහ කුරුඳු", "තේ සහ රබර්", "පොල් තෙල් සහ කොප්පරා", "කෝපි සහ කොකෝවා", "ගම්පොළ යුගය ආසන්නයේ පැමිණි චීන සංචාරකයා ලංකාවේ මැණික් හා කුරුඳු වර්ණනා කළේය."),
    q(T, "රොබට් නොක්ස්ගේ 'An Historical Relation of the Island Ceylon' කෘතිය 1681 දී ප්‍රකාශයට පත් වූ පසු ලැබුණු විශේෂත්වය කුමක්ද?", "යුරෝපීයයන්ට උඩරට රාජධානියේ පාලනය හා ජන ජීවිතය පිළිබඳ ප්‍රධාන මූලාශ්‍රයක් වීම", "සිංහලෙන් පමණක් පළ වීම", "මහනුවර රජු විසින් තහනම් කිරීම", "පෘතුගීසි රාජ්‍යය බිඳ වැටීමට හේතු වීම", "රොබට් නොක්ස්ගේ ග්‍රන්ථය යුරෝපීය භාෂා කිහිපයකටම පරිවර්තනය වූ ප්‍රාමාණික මූලාශ්‍රයකි."),
    q(T, "රාජ්‍ය පාලන නීති හා චාරිත්‍ර අඩංගු 'නීති නිඝණ්ඩුව' ග්‍රන්ථය කුමන යුගයේ නීති ක්‍රමය හැදෑරීමට ප්‍රයෝජනවත් වේද?", "මහනුවර යුගයේ උඩරට නීතිය", "අනුරාධපුර මුල් යුගයේ නීතිය", "පෘතුගීසි හමුදා නීතිය", "ලන්දේසි මුහුදු නීතිය", "බ්‍රිතාන්‍ය යුගයේ මුල් කාලයේ සම්පාදිත නීති නිඝණ්ඩුව උඩරට සාම්ප්‍රදායික නීති හා සිරිත් දක්වයි."),
    q(T, "ශ්‍රී ලංකාවේ චිත්‍ර කලාවේ ආරම්භක අවධිය ලෙස සැලකිය හැකි ප්‍රාග් ඓතිහාසික ගුහා චිත්‍ර හමු වී ඇති ස්ථානයක් කුමක්ද?", "දොරවකකන්ද හා තන්තිරිමලේ", "සීගිරිය පමණක්", "කැලණි විහාරය", "දළදා මාලිගාව", "කෑගල්ල දොරවකකන්ද, තන්තිරිමලේ හා බිල්ලෑව වැනි ස්ථානවල ප්‍රාග් ඓතිහාසික රේඛා චිත්‍ර හමුවේ."),
    q(T, "ප්‍රාග් ඓතිහාසික ගුහා චිත්‍ර නිර්මාණය කිරීමේදී මානවයා වර්ණ ලෙස බහුලව භාවිත කළ ද්‍රව්‍ය කවරේද?", "අළු, අඟුරු, මැටි හා ගුරුගල්", "තෙල් සායම් හා වාර්නිෂ්", "රසායනික ඩයි වර්ග", "ප්ලාස්ටික් තීන්ත", "ස්වාභාවික ඛනිජ හා අළු භාවිතයෙන් සතුන් හා ජ්‍යාමිතික රූප ඇඳ ඇත."),
    q(T, "වංශකතාවල එන ආදිවාසී ජනයාගේ මූලාරම්භය පිළිබඳ පුරාවෘත්තය මහාවංශයේ දැක්වෙන්නේ කවුරුන් ඇසුරින්ද?", "විජය හා කුවේණියගේ දරුවන් වූ ජීවහත්ථ හා දිසාලා", "දුටුගැමුණු හා අශෝකමාලා", "පණ්ඩුකාභය හා ස්වර්ණපාලි", "මහසෙන් හා සංඝමිත්තා", "මහාවංශය වැදි ජනයා පුලින්දයන් ලෙස හඳුන්වමින් විජය-කුවේණි පුරාවෘත්තයට සම්බන්ධ කරයි."),
    q(T, "කළු-රතු මැටි බඳුන් (Black and Red Ware) යන නම ලැබී ඇත්තේ කුමන නිෂ්පාදන ලක්ෂණයක් නිසාද?", "පිළිස්සීමේ තාක්ෂණය අනුව බඳුනේ ඇතුළත කළු පැහැයත් පිටත රතු පැහැයත් ගැනීම නිසා", "කළු හා රතු තීන්ත ආලේප කිරීම නිසා", "රතු ගඩොල් හා කළු ගල් එක් කිරීම නිසා", "රත්‍රන් ආලේප කිරීම නිසා", "ප්‍රතිවර්ත පිළිස්සීම් ක්‍රමය (inverted firing) මගින් මෙම ද්විත්ව වර්ණ ලැබී ඇත."),
    q(T, "ඉතිහාසය හැදෑරීමෙන් පුරවැසියෙකුට ලැබෙන ප්‍රධානම සමාජ ප්‍රයෝජනය කුමක්ද?", "අතීත අත්දැකීම්වලින් පාඩම් ඉගෙන වර්තමානය තේරුම් ගැනීම හා ජාතික අනන්‍යතාව හඳුනා ගැනීම", "සියලු විදේශිකයන්ට වෛර කිරීමට පුරුදු වීම", "වර්තමාන තාක්ෂණය ප්‍රතික්ෂේප කිරීම", "යුද්ධ ඇති කිරීමට ඉගෙන ගැනීම", "ඉතිහාසය මිනිස් සමාජයේ අතීත ගමන්මග හඳුනා ගෙන බුද්ධිමත් අනාගතයක් ගොඩනැගීමට මග පෙන්වයි."),
    q(T, "පූර්ව බ්‍රාහ්මී ශිලා ලේඛනවල සඳහන් වන 'ලෙණ' යන වචනයෙන් අදහස් කෙරෙන්නේ කුමක්ද?", "භික්ෂූන් වහන්සේලාට පූජා කළ ගල් ගුහාව හෙවත් ලෙන", "වැව් බැම්ම", "රාජ්‍ය භාණ්ඩාගාරය", "වෙළෙඳ නැව", "'සගස දිනෙ' යන්න සමඟ ලෙන් පූජා කිරීම සඳහන් කරන බ්‍රාහ්මී ලිපි දහසකට වඩා ලංකාවෙන් හමුවේ."),
    q(T, "පූර්ව බ්‍රාහ්මී ලෙන් ලිපිවල බහුලව දැකිය හැකි 'අගත අනගත චතුදිස සගස' යන පාඨයේ තේරුම කුමක්ද?", "පැමිණි නොපැමිණි සිව්දිග සංඝයා වහන්සේට පූජා කළ බව", "රජුට පමණක් අයිති බව", "විදේශිකයන්ට විකුණූ බව", "වැව් බදු ගෙවූ බව", "බුදු සසුනේ සිව්දිග මහා සංඝරත්නය උදෙසා ලෙන් පිදීම මෙයින් ප්‍රකාශ වේ."),
    q(T, "ශ්‍රී ලංකාවේ පැරණිතම සෙල්ලිපිවල බහුලව යෙදී ඇති 'ශක' හෝ 'මංගල' සංකේත මොනවාද?", "ස්වස්තිකය, මත්ස්‍ය සංකේතය සහ ත්‍රිරත්න ලකුණ", "කුරුසය හා අඩ සඳ", "සිංහ කොඩිය", "සීනුව හා පන්හිඳ", "පූර්ව බ්‍රාහ්මී ලිපි ආරම්භයේදී හෝ අවසානයේදී මංගල සංකේත ලෙස ස්වස්තික ආදිය කොටා ඇත."),
    q(T, "පුරාවිද්‍යාත්මක කැණීම්වලින් හමු වී ඇති 'රෝම රුලෙට් මැටි බඳුන්' (Rouletted Ware) ශ්‍රී ලංකාවේ කුමන ඓතිහාසික කරුණක් තහවුරු කරයිද?", "ක්‍රි.පූ. 2 වන සියවසේ සිට ක්‍රි.ව. 3 වන සියවස දක්වා ඉන්දියාව හා මධ්‍යධරණී කලාපය සමඟ තිබූ වෙළෙඳාම", "ලන්දේසි වෙළෙඳ ඒකාධිකාරය", "පෘතුගීසි ආගමනය", "බ්‍රිතාන්‍ය වතු ආර්ථිකය", "මන්තායි, අනුරාධපුරය හා තිස්සමහාරාමයෙන් රුලෙට් මැටි බඳුන් කැබලි හමු වී ඇත."),
    q(T, "චීන සංචාරක පාහියන් හිමියන් අනුරාධපුරයේ කොපමණ කාලයක් වැඩ සිට ධර්ම ග්‍රන්ථ පිටපත් කළේද?", "වසර දෙකක් (ක්‍රි.ව. 411 - 413 පමණ)", "මාස දෙකක්", "සති දෙකක්", "වසර විස්සක්", "පාහියන් හිමි අනුරාධපුර අභයගිරියේ වසර දෙකක් සිට විනය පිටකය ආදිය ලබාගෙන චීනයට වැඩම කළහ."),
    q(T, "බුදුරජාණන් වහන්සේගේ ලංකාගමන තුන පිළිබඳව විස්තර වන ප්‍රධාන දේශීය වංශකතා මොනවාද?", "දීපවංශය සහ මහාවංශය", "රාජාවලිය සහ සීතාවක හටන", "නිකාය සංග්‍රහය සහ සිදත් සඟරාව", "රොබට් නොක්ස්ගේ ග්‍රන්ථය", "මහියංගණය, නාගදීපය සහ කැලණියට බුදුන් වහන්සේ වැඩම කළ බව දීපවංශ හා මහාවංශ මුල් පරිච්ඡේදවල දැක්වේ."),
    q(T, "ශ්‍රී ලංකාවේ පැරණිතම අක්ෂර විකාශනය අධ්‍යයනය කිරීමේදී බ්‍රාහ්මී අක්ෂරවලින් පසු වර්ධනය වූ අක්ෂර මාලා අවධිය කුමක්ද?", "අපර බ්‍රාහ්මී අක්ෂර හා පසුකාලීන පල්ලව-ග්‍රන්ථ ආභාසිත සිංහල අක්ෂර", "ලතින් අක්ෂර", "අරාබි අක්ෂර", "සිරිලික් අක්ෂර", "ශතවර්ෂ ගණනාවක් තිස්සේ බ්‍රාහ්මී අක්ෂර වෙනස් වී වර්තමාන වටකුරු සිංහල අක්ෂර මාලාව බිහිවිය."),
    q(T, "පුරාවිද්‍යාත්මක කැණීම්වලින් 'අලියා' හෝ 'ගවයා' වැනි සතුන්ගේ ඇටකටු සහ ධාන්‍ය වර්ග හමුවීම අයත් වන්නේ කුමන අධ්‍යයන අංශයටද?", "පුරා ජීව විද්‍යාව සහ පුරා උද්භිද විද්‍යාව (Bio-archaeology)", "නාණක විද්‍යාව", "අභිලේඛන විද්‍යාව", "රාජ්‍ය පාලන විද්‍යාව", "සත්ත්ව ඇටකටු (Zooarchaeology) හා බීජ (Archaeobotany) අධ්‍යයනයෙන් පැරණි ආහාර හා පරිසරය හෙළි වේ."),
    q(T, "බටදොඹලෙන හා කිතුල්ගල බෙලිලෙන ආදී ස්ථානවලින් හමු වූ 'හීන් කුරුඳු', 'වල් කොස්' හා 'කැකුණ' අවශේෂ මගින් කුමක් තහවුරු වේද?", "බලංගොඩ මානවයා ශාකමය ආහාරද පුළුල් ලෙස ප්‍රයෝජනයට ගත් බව", "ඔවුන් මස් පමණක් ආහාරයට ගත් බව", "එවකට කෘෂි වෙළෙඳසැල් තිබූ බව", "වී ගොවිතැන වසර 30,000කට පෙර තිබූ බව", "දඩයමට අමතරව වනගත පලතුරු හා ඇට වර්ග බලංගොඩ මානවයාගේ ප්‍රධාන පෝෂණ මූලාශ්‍රයක් විය."),
    q(T, "ප්‍රාග් ඓතිහාසික මිනිසුන් තම මළවුන්ගේ ඇටකටු නැවත තැන්පත් කිරීමේ 'ද්විතීයික සුසාන' (Secondary Burials) ක්‍රමයක් අනුගමනය කළ බවට සාධක හමු වී ඇත්තේ කොහිද?", "රාවණා ඇල්ල හා බටදොඹලෙන", "කොළඹ කොටුව", "යාපනය කොටුව", "ගාලු කොටුව", "ඇටකටු කොටස් රතු ගුරුගල් තවරා තැන්පත් කර තිබීමෙන් ද්විතීයික සුසාන චාරිත්‍ර පැහැදිලි වේ."),
    q(T, "මූල ඓතිහාසික යුගයේ ජනතාව තඹ හා යකඩ වැනි ලෝහ උණු කිරීමට භාවිත කළ මැටි නළ හඳුන්වන්නේ කුමන නමකින්ද?", "කෝව හා හුළං බට (Crucibles and Tuyeres)", "පෝසිලේන් පිඟන්", "මැටි පහන්", "ජල නළ", "ලෝහ උණු කිරීමේ උදුන්වලට වාතය පිඹීමට යොදාගත් මැටි බට (Tuyeres) කැණීම්වලින් බහුලව හමුවේ."),
    q(T, "පැරණි ශ්‍රී ලංකාවේ 'ඉරණමඩු' සහ 'පතිරාජවෙල' වැනි වෙරළබඩ ස්ථානවලින් හමු වූ ගල් ආයුධ පෙන්වා දෙන ඓතිහාසික වැදගත්කම කුමක්ද?", "මීට වසර ලක්ෂයකටත් එහා පුරාශිලා මානව ක්‍රියාකාරකම් මෙරට පැවති බවට ඉඟි සැපයීම", "රෝම නැව් ගොඩබට බව", "චෝල ආක්‍රමණ සිදු වූ බව", "මුහුදුබඩ වරායන් විනාශ වූ බව", "දකුණුදිග වෙරළේ පැරණි වැලි ස්තරවලින් පුරාණ ගල් ආයුධ හමුවී තිබේ."),
    q(T, "පුරාවිද්‍යාත්මක කැණීමකදී කිසියම් ස්ථානයක මතුපිට පරීක්ෂා කිරීමේ මුල් පියවර හඳුන්වන්නේ කුමන නමකින්ද?", "ක්ෂේත්‍ර ගවේෂණය (Field Survey)", "රසායනාගාර විශ්ලේෂණය", "සංරක්ෂණය", "ප්‍රදර්ශනය", "කැණීමක් ආරම්භ කිරීමට පෙර මතුපිට ඇති පුරාවස්තු හා භූ ලක්ෂණ නිරීක්ෂණය කිරීම ක්ෂේත්‍ර ගවේෂණයයි."),
    q(T, "ලංකාවේ පැරණි ශිලා ලේඛන කියවීමේදී වංශකතාවල සඳහන් නොවන ඇතැම් ප්‍රාදේශීය පාලකයන් පිළිබඳවද තොරතුරු හමුවන්නේ කුමන ප්‍රදේශවලින්ද?", "රුහුණු සහ දිගාමඩුල්ල (බෝවත්තේගල, කොටාදැමූහෙල)", "කොළඹ කොටුව", "නුවරඑළිය", "මීගමුව", "බෝවත්තේගල හා කොටාදැමූහෙල ලිපිවලින් කතරගම ක්ෂත්‍රියන් වැනි ප්‍රාදේශීය රජ පෙළපත් හෙළි වේ."),
    q(T, "වංශකතා සාහිත්‍යයේ එන 'අත්තනගලු වංශය' (හත්ථවනගල්ල විහාර වංශය) කුමන රජුගේ ජීවිත කතාවට ප්‍රධාන වශයෙන් සම්බන්ධද?", "සිරිසඟබෝ රජුගේ", "දුටුගැමුණු රජුගේ", "කාශ්‍යප රජුගේ", "පරාක්‍රමබාහු රජුගේ", "දඹදෙණි යුගයේ රචිත අත්තනගලු වංශය සිරිසඟබෝ රජුගේ ධාර්මික පාලනය හා පරිත්‍යාගය විස්තර කරයි."),
    q(T, "රාජරත්නාකරය නම් ඓතිහාසික සිංහල ග්‍රන්ථය රචනා කරන ලද්දේ කුමන යුගයේදීද?", "කෝට්ටේ හෝ සීතාවක/මහනුවර මුල් යුගයේ (වලගම්පාය අභයරාජ පිරිවෙන්පති හිමි)", "අනුරාධපුර මුල් යුගයේ", "මධ්‍යශිලා යුගයේ", "බ්‍රිතාන්‍ය යුගයේ අවසානයේ", "රාජරත්නාකරය සිංහලෙන් රචිත ලංකාවේ රාජවංශය හා ශාසනික තොරතුරු අඩංගු මූලාශ්‍රයකි."),
    q(T, "පෘතුගීසි ජාතික ජොආඕ රිබෙයිරෝ (Joao Ribeiro) රචනා කළ ග්‍රන්ථය මගින් ආවරණය වන්නේ කුමන ඉතිහාස පරිච්ඡේදයද?", "පෘතුගීසි පාලන සමය හා ලන්දේසීන් අතින් පෘතුගීසීන් පරාජය වීම", "අනුරාධපුර වැව් ඉදිකිරීම", "බලංගොඩ මානවයා", "විජය කුමරුගේ පැමිණීම", "සොල්දාදුවෙකු ලෙස ලංකාවේ සේවය කළ රිබෙයිරෝගේ වාර්තාව 17 වන සියවසේ සිදුවීම් දක්වයි."),
    q(T, "මහාචාර්ය විල්හෙල්ම් ගයිගර් විසින් සංස්කරණය කරන ලද 'චූලවංශය' ඉංග්‍රීසියට පරිවර්තනය කිරීමේදී සහාය වූයේ කවුද?", "සී. මේබල් රික්මර්ස් (C. Mabel Rickmers)", "රොබට් නොක්ස්", "ෆ්‍රෙඩ්රික් නෝර්ත්", "එච්.සී.පී. බෙල්", "ගයිගර්ගේ ජර්මානු පරිවර්තනය ඇසුරෙන් මේබල් රික්මර්ස් චූලවංශය ඉංග්‍රීසියට පරිවර්තනය කළාය."),
    q(T, "සෙල්ලිපියක ඇති අක්ෂරවල හැඩය අනුව එම ලිපිය කුමන සියවසට අයත්දැයි තීරණය කිරීමේ විද්‍යාත්මක ක්‍රමය කුමක්ද?", "පුරාලිපි විද්‍යාත්මක කාලනිර්ණය (Paleographical Dating)", "කාබන් 14 පරීක්ෂණය", "ගුවන් ඡායාරූපකරණය", "රසායනික සේදීම", "එක් එක් සියවසේ අක්ෂර හැඩතල වෙනස් වන බැවින් අක්ෂර රූප අනුව සෙල්ලිපියක කාලය නිගමනය කළ හැකිය."),
    q(T, "පුරාවිද්‍යාත්මක ස්ථාන සංරක්ෂණය කිරීමේදී 'නැවත ගොඩනැගීම' වෙනුවට පවතින නටබුන් ආරක්ෂා කිරීම හඳුන්වන්නේ කෙසේද?", "තහවුරු කිරීම සහ සංරක්ෂණය (Conservation and Consolidation)", "සම්පූර්ණ නවීකරණය", "විනාශ කිරීම", "පෞද්ගලික විකිණීම", "පුරාවිද්‍යාත්මක වටිනාකම නොනැසී පවතින පරිදි මුල් ස්වරූපය ආරක්ෂා කිරීම සංරක්ෂණයේ මූලධර්මයයි."),
    q(T, "ශ්‍රී ලංකාවේ පැරණිතම බෞද්ධ ස්තූප ගොඩනැගීමේදී භාවිත කළ 'වැඩුණු ගඩොල්' මත මිනුම් හා අක්ෂර කොටා තිබීමෙන් හෙළි වන්නේ කුමක්ද?", "ඉදිකිරීම් සඳහා පෙදරේරු ශිල්පීන් හා අක්ෂර දත් කම්කරුවන් සිටි බව", "ගඩොල් පිටරටින් ගෙන්වූ බව", "ගඩොල් භාවිතය තහනම් වූ බව", "පෘතුගීසීන් ගඩොල් තැනූ බව", "අනුරාධපුර ස්තූප හා විහාර ගඩොල්වල සංඛ්‍යා හා නම් කොටා තිබීමෙන් සාක්ෂරතාව හා කළමනාකරණය පෙනේ."),
    q(T, "අනුරාධපුර ජේතවනාරාම කැණීම්වලින් හමු වූ රන් තහඩු හතක ලියූ 'පංචවිංශති සහස්රිකා ප්‍රඥාපාරමිතා' සූත්‍ර කොටස්වලින් හෙළි වන්නේ කුමක්ද?", "ක්‍රි.ව. 9 වන සියවසේ මහායාන ධර්මය හා රන් තහඩුවල පොත් ලිවීමේ කලාව පැවති බව", "ලන්දේසි ආගම", "ප්‍රාග් ඓතිහාසික දඩයම", "බ්‍රිතාන්‍ය නීතිය", "ජේතවනාරාමයෙන් හමු වූ මෙම රන් පත්ඉරු සංස්කෘත භාෂාවෙන් හා සිංහල අක්ෂරවලින් ලියා ඇත."),
    q(T, "මූල ඓතිහාසික යුගයේ 'වලවේ ගං නිම්නයේ රිදියගම' කැණීම්වලින් හෙළි වූ වැදගත් ආර්ථික කරුණ කුමක්ද?", "පැරණි කර්මාන්ත, පබළු නිෂ්පාදනය හා විදේශ වෙළෙඳ සබඳතා පැවති බව", "තේ කර්මාන්තශාලා තිබූ බව", "බ්‍රිතාන්‍ය කඳවුරක් තිබූ බව", "දුම්රිය ස්ථානයක් තිබූ බව", "රිදියගම මුල් යකඩ යුගයේ සිටම ක්‍රියාත්මක වූ ප්‍රධාන දකුණු ලංකා ජනාවාසයකි."),
    q(T, "පැරණි ලංකාවේ 'මහාතිත්ථ' (මාන්තොට) මෙන්ම දකුණු වෙරළේ ප්‍රධාන වෙළෙඳ මධ්‍යස්ථානයක් වූ 'කිරින්ද - ගොඩවාය' කලාපයේ තිබූ වටිනාකම කුමක්ද?", "රුහුණු රාජධානිය විදේශ වෙළෙඳ ලෝකය සමඟ සම්බන්ධ කළ ප්‍රධාන ද්වාරය වීම", "කඳුකර මාලිගා පැවතීම", "මිහිඳු හිමි වැඩම කිරීම", "ලන්දේසි අගනුවර වීම", "ගොඩවාය හා මහාගාම ආශ්‍රිත කැණීම්වලින් විදේශීය කාසි හා මැටි බඳුන් රැසක් හමුවී ඇත."),
    q(T, "ශ්‍රී ලංකාවේ 'ප්‍රාග් ඓතිහාසික යුගයේ' ජනගහනය ප්‍රධාන වශයෙන් සීමා වී සිටි පරිසර කලාප මොනවාද?", "තෙත් කලාපයේ ගල් ලෙන්, වියළි කලාපයේ වෙරළබඩ තැනිතලා හා මධ්‍යම කඳුකර තැනිතලා", "අගනුවර මාලිගා තුළ පමණක්", "කුඩා දූපත් තුළ පමණක්", "කාන්තාරවල පමණක්", "දේශගුණය හා ආහාර සම්පත් අනුව දිවයිනේ සෑම පාරිසරික කලාපයකම බලංගොඩ මානවයා විසූහ."),
    q(T, "බලංගොඩ මානවයාගේ ලිංගිකත්වය, වයස හා ජීවන රටාව හඳුනා ගැනීමට වඩාත් ඉවහල් වන පුරාවිද්‍යාත්මක සාධක මොනවාද?", "ශ්‍රෝණි අස්ථි, හිස් කබල, දත් සහ අතපය ඇටකටු", "ගල් ආයුධ පමණක්", "ගුහා චිත්‍ර පමණක්", "වංශකතා විස්තර", "මානව අස්ථි විද්‍යාව (Osteology) මගින් පුරාණ මිනිසුන්ගේ වයස, උස හා රෝගාබාධ හඳුනා ගැනේ."),
    q(T, "ශ්‍රී ලංකාවේ 'පූර්ව ඓතිහාසික යුගයේ' භාවිත කළ මැටි බඳුන් නිපදවීමේදී ඒවා හැඩගැන්වීමට යොදාගත් ප්‍රධාන තාක්ෂණික උපකරණය කුමක්ද?", "සකපෝරුව (Potter's Wheel)", "විදුලි ලේත් යන්ත්‍රය", "ත්‍රිමාණ මුද්‍රණ යන්ත්‍රය", "ලෝහ අච්චු", "ඉතා සමමිතික හා සිහින් බිත්ති සහිත මැටි බඳුන් සකපෝරුව භාවිතයෙන් නිමවා ඇත."),
    q(T, "පුරාවිද්‍යාත්මක මූලාශ්‍ර හා සාහිත්‍ය මූලාශ්‍ර අතර පරස්පරතා ඇති වූ විට ඉතිහාසඥයන් ගනු ලබන විද්‍යාත්මක පියවර කුමක්ද?", "දෙපාර්ශ්වයේම සාක්ෂි සංසන්දනය කර සමකාලීන පුරාවිද්‍යාත්මක සාධකවලට ප්‍රමුඛත්වය දීම", "සියලු ඉතිහාස පොත් ඉවත දැමීම", "ජනකතා පමණක් පිළිගැනීම", "අනුමානයෙන් අලුත් කතාවක් ලිවීම", "ශිලා ලේඛන වැනි සමකාලීන ලිඛිත හා භෞතික සාධක කාලයෙන් පසුව ලියූ වංශකතා පරීක්ෂාවට යොදාගනී."),
    q(T, "පැරණි ලංකාවේ දේශීය හා විදේශීය වෙළෙඳුන් 'බැංකු' වැනි මූල්‍ය ආයතන ලෙස ක්‍රියා කළ ආකාරය දැක්වෙන මූලාශ්‍රය කුමක්ද?", "තෝණිගල ගිරි ලිපිය (වෙළෙඳ ශ්‍රේණියක ධාන්‍ය තැන්පත් කිරීම)", "මහාවංශයේ පළමු පරිච්ඡේදය", "සැළලිහිණි සන්දේශය", "රොබට් නොක්ස්ගේ දිනපොත", "කළහුමණක නම් වෙළෙඳ සංගමයක ධාන්‍ය තැන්පත් කර පොලියෙන් දානය දීම තෝණිගල ලිපියේ දැක්වේ."),
    q(T, "සීගිරිය අසල පොතාන ලෙනෙන් හමු වූ මානව ඇටසැකිල්ල කුමන කාලපරිච්ඡේදයට අයත් බව කාලනිර්ණය කර ඇත්ද?", "මධ්‍යශිලා යුගයට (වසර 6,000කට පමණ පෙර)", "පොළොන්නරු යුගයට", "ලන්දේසි යුගයට", "කෝට්ටේ යුගයට", "සීගිරිය පොතාන හා අලිගල කැණීම්වලින් මධ්‍යශිලා මානව අවශේෂ හමුවී තිබේ."),
    q(T, "අනුරාධපුර ඇතුළුනුවර කැණීම්වලදී මුල් යුගයේ අශ්ව ඇටකටු හමුවීමෙන් කුමන ඓතිහාසික කරුණ තහවුරු වීද?", "ක්‍රි.පූ. 6 වන සියවස තරම් ඈත කාලයේ සිටම ඉන්දියාව සමඟ අශ්වයන් ගෙන ඒමේ සබඳතා තිබූ බව", "අශ්වයන් ලංකාවේ වනාන්තරවල ස්වභාවිකව බිහි වූ බව", "ලන්දේසීන් අශ්වයන් ගෙන ආ බව", "අශ්වයන් ආහාරයට ගත් බව", "අශ්වයා ලංකාවට ආවේණික සතෙකු නොවන බැවින් මුල් කාලයේ සිටම ආනයනික සබඳතා තිබූ බව පෙනේ."),
    q(T, "බ්‍රිතාන්‍ය ජාතික හියු නෙවිල් (Hugh Nevill) සහ එච්.ඩබ්ලිව්. කොඩ්‍රින්ටන් යන විද්වතුන් ලංකා ඉතිහාසයට කළ ප්‍රධාන සේවය මොනවාද?", "පුස්කොළ පොත් එකතු කිරීම සහ පැරණි කාසි හා ඉතිහාසය පිළිබඳ ග්‍රන්ථ රචනය", "කෝපි වගාව හඳුන්වා දීම", "දුම්රිය මාර්ග තැනීම", "තේ කර්මාන්තශාලා ඉදිකිරීම", "කොඩ්‍රින්ටන්ගේ 'Ceylon Coins and Currency' කෘතිය නාණක විද්‍යාවේ ප්‍රාමාණික මූලාශ්‍රයකි."),
    q(T, "ශ්‍රී ලංකාවේ අභිලේඛන අතර බහුලව හමුවන 'නිදහස් ලිපි' හෙවත් 'අත්තානි කණු' (Immunity Grants) මගින් අදහස් කෙරෙන්නේ කුමක්ද?", "රාජ්‍ය නිලධාරීන්ට විහාර ඉඩම්වලට ඇතුළු වීම හෝ බදු අය කිරීම තහනම් කරන රාජකීය ආඥා", "රජවරුන්ගේ මරණ දැන්වීම්", "වෙළෙඳ මිල ගණන්", "යුද ගිවිසුම්", "ක්‍රි.ව. 9-10 සියවස්වල රජවරුන් විහාරස්ථානවලට පරිත්‍යාග කළ ගම්වලට නිදහස් වරප්‍රසාද දුන් ටැම් ලිපි වේ."),
    q(T, "පැරණි ලංකාවේ බෞද්ධ ස්තූප හා විහාර ගොඩනැගිලිවල දක්නට ලැබෙන 'රන්, රිදී, මැණික් හා කාසි' නිධන් කළ 'ධාතු ගර්භ' පුරාවිද්‍යාඥයන්ට වැදගත් වන්නේ ඇයි?", "ඒවායේ අඩංගු පුරාවස්තු මගින් එම ඉදිකිරීම් සිදු කළ නියම කාලය හා කලා තාක්ෂණය තහවුරු වන බැවින්", "රත්‍රන් විකුණා මුදල් සෙවීමට", "රජුගේ හමුදා සංඛ්‍යාව ගණන් කිරීමට", "ලිපි කියවීමට", "දැදිගම සූතිඝර චෛත්‍යය වැනි ස්ථානවල ධාතු ගර්භවලින් අගනා ලෝහ හා මැටි නිර්මාණ හමු වී ඇත."),
    q(T, "මිහිඳු හිමියන් වැඩමවීමට පෙර සිටම අනුරාධපුරයේ 'ශිව' සහ 'බ්‍රාහ්මණ' ආගමික විශ්වාස පැවති බවට සාධක සපයන මූලාශ්‍රය කුමක්ද?", "මහාවංශයේ 10 වන පරිච්ඡේදය (පණ්ඩුකාභය රජුගේ ආගමික ගොඩනැගිලි විස්තරය)", "පූජාවලිය", "රාජාවලිය", "නිකාය සංග්‍රහය", "පණ්ඩුකාභය රජු බ්‍රාහ්මණ, නිඝණ්ඨ, ශිව හා පරිබ්‍රාජකයන්ට ආරාම තැනූ බව මහාවංශයේ සඳහන් වේ."),
    q(T, "ශ්‍රී ලංකාවේ ක්‍රිස්තු වර්ෂ 1 සිට 12 වන සියවස දක්වා පාලන සමයන් නිවැරදිව කාලනිර්ණය කිරීමට දේශීය වංශකතා සමඟ සැසඳූ ප්‍රධාන විදේශීය වාර්තා මොනවාද?", "චීන රාජ සභා වාර්තා සහ දකුණු ඉන්දීය ශිලා ලේඛන", "ඇමරිකානු පුවත්පත්", "ඕස්ට්‍රේලියානු ලේඛන", "ප්‍රංශ විප්ලව වාර්තා", "මහානාම, භාතිකාභය හා කිත්සිරිමෙවන් රජවරුන්ගේ චීන තානාපති ගමන් චීන වාර්තාවල දැක්වේ."),
    q(T, "පුරාවිද්‍යාත්මක කැණීම්වලදී 'රේඩියෝ කාබන්' කාලනිර්ණය (C-14) භාවිත කළ හැකි උපරිම කාල සීමාව කොපමණද?", "වසර 50,000ක් පමණ දක්වා", "වසර 500ක් පමණක්", "වසර කෝටි 100ක්", "වසර 100ක් පමණක්", "කාබන්-14 සමස්ථානිකයේ අර්ධ ආයු කාලය අනුව වසර 50,000ක් දක්වා කාබනික ද්‍රව්‍ය කාලනිර්ණය කළ හැකිය."),
    q(T, "ඉරණමඩු වැනි අවුරුදු 50,000කට වඩා පැරණි කාබනික නොවන වැලි ස්තර කාලනිර්ණය කිරීමට පුරාවිද්‍යාඥයන් භාවිත කරන නවීන ක්‍රමය කුමක්ද?", "ප්‍රකාශ සංදීප්ත කාලනිර්ණය (OSL - Optically Stimulated Luminescence)", "මහාවංශය කියවීම", "කාසි ගණන් කිරීම", "දින දර්ශනය බැලීම", "බූන්දල-පතිරාජවෙල පස් ස්තර කාලනිර්ණය කිරීමට තාප හා ප්‍රකාශ සංදීප්ත (TL/OSL) ක්‍රම භාවිත කෙරිණි."),
    q(T, "සාහිත්‍ය මූලාශ්‍ර අධ්‍යයනයේදී 'ටීකා ග්‍රන්ථ' යනුවෙන් හඳුන්වන්නේ මොනවාද?", "අටුවා ග්‍රන්ථවල ඇති ගැඹුරු හෝ අපැහැදිලි කරුණු විස්තර කිරීමට පසුව ලියූ විවරණ ග්‍රන්ථ", "ප්‍රාග් ඓතිහාසික ගල් ආයුධ", "රජවරුන්ගේ බදු ලැයිස්තු", "පෘතුගීසි කවි පොත්", "වංසත්ථප්පකාසිනිය වැනි ටීකා මූලික පෙළ හා අටුවා පැහැදිලි කිරීමට ලියැවුණි."),
    q(T, "ලංකාවේ චූලවංශයේ අවසාන කොටස (දෙවන කොටස) සම්පාදනය කළේ කුමන රජුගේ සමයේ හා කවුරුන් විසින්ද?", "කීර්ති ශ්‍රී රාජසිංහ රජ සමයේ තිබ්බටුවාවේ ශ්‍රී සිද්ධාර්ථ බුද්ධරක්ඛිත හිමි විසින්", "පණ්ඩුකාභය රජ සමයේ මහානාම හිමි", "මහසෙන් රජ සමයේ බුද්ධඝෝෂ හිමි", "විජයබාහු රජ සමයේ සරණංකර හිමි", "18 වන සියවසේ මහනුවර යුගය දක්වා චූලවංශය තිබ්බටුවාවේ බුද්ධරක්ඛිත හිමියන් අතින් සම්පූර්ණ විය."),
    q(T, "බුලත්සිංහල පාහියන්ගල ලෙන අධ්‍යයනය කිරීමෙන් හෙළි වූ විශේෂිත ප්‍රාග් ඓතිහාසික ආභරණ මොනවාද?", "සත්ත්ව දත්, මුහුදු බෙලි කටු හා ඇටකටු සිදුරු කර තැනූ පබළු", "රන් මාල හා මුදු", "දියමන්ති වළලු", "රිදී පාද සළඹ", "වසර 30,000කට පෙර බලංගොඩ මානවයා සිදුරු කළ මෝර දත් හා බෙලි කටු පබළු භාවිත කර ඇත."),
    q(T, "මූල ඓතිහාසික යුගයේ 'වී ගොවිතැන' මෙරට ආරම්භ වූ බවට හමු වී ඇති සෘජු පුරාවිද්‍යාත්මක සාධකය කුමක්ද?", "අනුරාධපුරය, ඉබ්බන්කටුව හා මන්තායි කැණීම්වලින් පිළිස්සුණු වී ඇට සහ දහයියා මිශ්‍ර මැටි හමුවීම", "පෘතුගීසි ලේඛන", "ලන්දේසි සහල් බදු", "ටොලමිගේ සිතියම", "පිළිස්සුණු වී ඇට හා මැටි බඳුන්වල දහයියා සලකුණු ක්‍රි.පූ. 900-600 සමයේ වී වගාව තහවුරු කරයි."),
    q(T, "ඉතිහාසය හැදෑරීමේදී දේශීය හා විදේශීය මූලාශ්‍ර දෙවර්ගයම එකසේ අත්‍යවශ්‍ය වන්නේ ඇයි?", "එක් මූලාශ්‍රයක මගහැරෙන හෝ පක්ෂග්‍රාහී කරුණු අනෙක් මූලාශ්‍රයෙන් තහවුරු හා සංසන්දනය කළ හැකි බැවින්", "එකම තොරතුර නැවත නැවත කියවීමට", "විභාග ප්‍රශ්න පත්‍ර දිගු කිරීමට", "දේශීය මූලාශ්‍ර සම්පූර්ණයෙන් බොරු බැවින්", "විවිධ මූලාශ්‍ර ඒකාබද්ධ කිරීමෙන් වඩාත් මධ්‍යස්ථ හා නිවැරදි ඓතිහාසික චිත්‍රයක් ගොඩනැගේ."),
    q(T, "මහාවංශයේ සඳහන් අශෝක අධිරාජ්‍යයා හා දේවානම්පියතිස්ස රජු අතර මිත්‍රත්වය ඉන්දියානු පුරාවිද්‍යා සාධකවලින් තහවුරු වන්නේ කෙසේද?", "අශෝක අධිරාජ්‍යයාගේ 2 වන හා 13 වන ගිරි ලිපිවල 'තම්බපණ්ණි' ගැන සඳහන් වීමෙන්", "තාජ්මහලේ ලියා තිබීමෙන්", "මුම්බායි වරායේ කාසිවලින්", "දිල්ලි සුල්තාන් වාර්තාවලින්", "අශෝකගේ සෙල්ලිපිවල 'තම්බපණ්ණි' නමින් ලංකාව හා ධර්ම දූත සබඳතා සඳහන් කර ඇත.")
  )
}

